insert into clientes (nome, pais, segmento, contatos) select 'Grupo Petersen', 'Argentina', 'Banco', 'Grupo: Carolina "Caro" (lidera el proyecto), Ricardo "Richard", "Macu", Mariana (integraciones de API), "Ale", Adrián, Mario [apellidos y cargos a confirmar]. Visa: Gabriela "Gaby", Damián "Dami", Cindy (Tesorería), Alexis (productos digitales Cono Sur), Débora (Benefits), Ale Rosa y Agustín Cánovas (BD). Prisma: Diego Echevarría [grafía a confirmar].' where not exists (select 1 from clientes where lower(nome)=lower('Grupo Petersen'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'Grupo Petersen — Proyecto Fusión (PMO integración bancaria)', 'Em andamento', 'Bruno Medeiros', null, '2026-11-12'::date, 'PMO de Visa para la integración bancaria del Grupo Petersen: Banco Entre Ríos (BERSA) y Banco San Juan se integran al Banco Santa Fe, que cambia de nombre e imagen; Banco Santa Cruz queda separado. No nace un banco nuevo. Todos procesan con Prisma y ninguno es principal member. Acompañamiento dicho de 9 meses, hasta julio de 2027. Desiree Ovejero es client facing. Solo VCA, sin CS. Fuente: transcripciones automáticas no validadas.', 'amarelo' from clientes c where lower(c.nome)=lower('Grupo Petersen') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')), 'Gobernanza PMO', 'PMO', 'Em curso', false, 'Bruno Medeiros', null, 'Semanal con el cliente el jueves 19/11; armar el archivo único de seguimiento.', 'Kickoff hecho el 12/11. Semanal hoy los jueves; Desi quiere pedir cambio a miércoles. Propuesta interna de dos cadencias: banco+Visa y banco+Visa+Prisma.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Gobernanza PMO'));
