insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Grupo Petersen')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')), 'adhoc', '2026-11-12'::date, 'Sesión introductoria con Tesorería Visa', 'Tesorería Visa explicó que la fusión exige revisar numéricos de tesorería, jerarquías y cuentas de liquidación, licencias y nombres legales. Cindy pidió un relevamiento interno antes de accionar a Prisma; Damián indicó que hay tiempo suficiente. El cliente pidió que el tema no sea bloqueante.', 'Primero análisis interno de Visa, después devolución al grupo y luego el mismo mensaje a Prisma, de preferencia en sesión conjunta.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and r.data='2026-11-12'::date and lower(r.titulo)=lower('Sesión introductoria con Tesorería Visa'));
