insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Grupo Petersen')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')), 'adhoc', '2026-11-12'::date, 'Alineamiento interno Visa post Tesorería', 'El equipo concluyó que la sesión fue demasiado técnica y que faltó la tesorería del banco. Se revisó qué son los numéricos por BIN y dónde obtenerlos. Desi propuso dos cadencias semanales, una con Prisma.', 'Reunión interna con cada equipo de Visa antes de cada sesión con el cliente.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and r.data='2026-11-12'::date and lower(r.titulo)=lower('Alineamiento interno Visa post Tesorería'));
