insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Grupo Petersen')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')), 'adhoc', '2026-11-16'::date, 'Demo VDMU', 'Alexis presentó el Visa Dynamic Metadata Updater para cambiar el arte de todo el parque tokenizado en la fusión, sin desarrollo del emisor. Solo aplica a credenciales Visa y por account range; cobro desde 01/02/2027. La sesión con Prisma prevista para ese día no se concretó.', 'Usar VDMU en lugar de integrar la API de metadata. No pedir activación anticipada.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and r.data='2026-11-16'::date and lower(r.titulo)=lower('Demo VDMU'));
