insert into clientes (nome, pais, segmento, contatos) select 'BancoEstado', 'Chile', 'Banco', 'Ángela (lidera el proyecto por el banco); Francesca Jones (jefatura de Ángela); Rodrigo Miranda (FIME, compras, marketing); Cintia Vázquez (coordinación) [grafía a confirmar]; Óscar Vázquez (Scrum Master de la célula de la app, enlace con Veritran); Claudio Alvarado (accesos, PRM, reuniones con Apple); Felipe Muñoz (líder técnico); Humberto Contreras (autorizador); Aldo (prevención de fraude). Terceros: Veritran (integrador de la app y del SDK; contacto Agustina), Apple, FIME.' where not exists (select 1 from clientes where lower(nome)=lower('BancoEstado'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'BancoEstado — Visa Digital Enablement SDK + Apple Pay', 'Em andamento', 'Jenny Johansen (lidera) / Bruno Medeiros (PM funcional de apoyo)', 'Lorena Retamales', '2026-09-15'::date, 'Consultoría Visa de acompañamiento para que BancoEstado implemente el SDK Visa Digital Enablement (Push Provisioning y Wallet Extension, modo headless, integrado por Veritran) y lance Apple Pay. Visa orienta y valida; no desarrolla, no certifica ni gestiona proveedores del banco. Contrato firmado la primera semana de septiembre (día exacto a confirmar); la fecha de inicio registrada es la del kickoff general (15/09/2026). Al 16/11/2026: 10 de 10 prerrequisitos de apertura cumplidos funcionalmente, apertura del proyecto técnico solicitada a CS y kickoff técnico el 25/11 según la Weekly Tech interna del 16/11 (en la weekly con el cliente del 11/11 se esperaba la semana del 16/11). Objetivo del banco: usuarios enrolando Apple Pay en mayo de 2027. Semáforo sugerido ámbar: apertura atrasada frente a la meta del 15/10, FIME sin contrato, Tap to Add sin desarrollar y cronograma sin holgura.', 'amarelo' from clientes c where lower(c.nome)=lower('BancoEstado') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'Prerrequisitos y apertura del proyecto técnico', 'Gobernanza / CS', 'Em curso - atrasado', true, 'Jenny Johansen / Bruno Medeiros', 'Fernando Núñez (designación formal pendiente)', 'Obtener el OK formal de CS (Lorena Retamales / Melina) y realizar el kickoff técnico el 25/11.', 'Kickoff general el 15/09 con 7 de 10 prerrequisitos. Los tres restantes cerraron así: contrato Apple en el Partner Hub (antes del 14/10), registro de Veritran aprobado en PRM (informado el 04/11) y soporte de PAN Source 06 (capacitación del 05/11: el banco ya lo soporta). La meta de apertura era el 15/10. El 11/11 la apertura estaba solicitada y faltaba el OK escrito de CS; la Weekly Tech del 16/11 fija el kickoff técnico para el 25/11, con apertura oficial después.', 'amarelo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Prerrequisitos y apertura del proyecto técnico'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Prerrequisitos y apertura del proyecto técnico')), 'Kickoff general (7/10 prerrequisitos)', '2026-09-15'::date, true, 0 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Prerrequisitos y apertura del proyecto técnico')) and lower(m.nome)=lower('Kickoff general (7/10 prerrequisitos)'));
