insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'SDK Visa Digital Enablement', 'SDK', 'Em curso', true, 'Banco / Veritran (Óscar Vázquez)', null, 'Recibir la programación detallada de Veritran y reagendar la sesión técnica con los especialistas de SDK de Visa.', 'El banco integra en modo headless con Push Provisioning y Wallet Extension; versión entregada 5.9. La integración la hace Veritran y comenzó en octubre; el banco validó internamente un diagrama de solución sin revisión de Visa. Desarrollo estimado en 18 semanas, con término en febrero de 2027. Primera reunión de planificación de Veritran el 09/11 y reunión técnica el 12/11.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('SDK Visa Digital Enablement'));
