insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'Apple Pay — requisitos funcionales Apple', 'Apple Pay', 'Em curso', true, 'Banco (Ángela, Claudio Alvarado) con apoyo de Francisco (producto Visa)', 'Fernando Núñez (designación formal pendiente)', 'Fijar en el kickoff técnico el hito de Tap to Add y tratar artes de tarjeta y freeze de diciembre.', 'Contrato Apple firmado y cargado en el Partner Hub antes del 14/10; cerca de 55 cuestionarios abiertos para áreas internas del banco. El banco mantiene reuniones periódicas con Apple y declara que no piensa pedir excepciones. Tap to Add se flexibilizó solo para la apertura: es mandatorio de Apple y el banco no lo tenía desarrollado. Pendientes: Wallet Extension con biometría facial (tarea de Apple), artes de la Cuenta RUT, marketing, reglas de VRM y whitelist, alcance Mastercard.', 'amarelo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Apple Pay — requisitos funcionales Apple'));
