insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'Certificación FIME', 'Certificación', 'Pendente', true, 'Banco (Rodrigo Miranda, compras)', null, 'Recibir la propuesta comercial de FIME, firmar el contrato y reservar el laboratorio en los primeros días de enero.', 'Contrato directo del banco con el laboratorio. NDA firmado por el banco el 19/10; primera reunión hecha antes del 04/11; el banco envió la información y espera la propuesta comercial. FIME recomienda solicitar el laboratorio a inicios de enero para comenzar pruebas en la segunda quincena de febrero: 25 días hábiles (5 de precertificación con los desarrollos en producción, más 10 y 10 de certificación formal).', 'amarelo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Certificación FIME'));
