insert into riscos (projeto_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'Los atrasos del banco aparecen tarde en los reportes (Tap to Add figuraba como listo sin estarlo); alta sensibilidad ejecutiva en el banco.', 'riesgo', 'media', 'Jenny Johansen / Bruno Medeiros', 'en_mitigacion', 'Pedir evidencia por ítem, minuta con las notas en el cuerpo del correo y reporte ejecutivo bimestral.' where not exists (select 1 from riscos x where x.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(x.descricao)=lower('Los atrasos del banco aparecen tarde en los reportes (Tap to Add figuraba como listo sin estarlo); alta sensibilidad ejecutiva en el banco.'));
