insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BancoEstado')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'adhoc', '2026-09-09'::date, 'Sesión de prerrequisitos: requisitos funcionales de Apple', 'Francisco recorrió con el banco la guía de requisitos funcionales de Apple versión 3.5. El banco planea autenticación por SMS y call center con IVR y un segundo factor propio en el push provisioning; Visa advirtió que Apple hoy pide verificación en la app. Se trató el ciclo de vida plástico versus token con un autorizador que decide por PAN.', 'Formalizar por escrito todo acuerdo o excepción con Apple y canalizarlo por las herramientas formales. Copiar siempre a Jenny y Bruno en los correos del proyecto.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and r.data='2026-09-09'::date and lower(r.titulo)=lower('Sesión de prerrequisitos: requisitos funcionales de Apple'));
