insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BancoEstado')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'semanal', '2026-09-30'::date, 'Weekly con el cliente', 'Primera weekly con la planilla Excel. El Comité Ejecutivo del banco aprobó el 29/09 la minuta que habilita la compra directa con Apple y FIME. Se fijó como meta tener todos los prerrequisitos y abrir el proyecto técnico el 15/10. El registro de Veritran quedó marcado en riesgo.', 'Meta de apertura 15/10. Preparar un one-pager para el Comité Ejecutivo del banco, con frecuencia bimestral.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and r.data='2026-09-30'::date and lower(r.titulo)=lower('Weekly con el cliente'));
