insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BancoEstado')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'adhoc', '2026-10-06'::date, 'Revisión interna del one-pager ejecutivo', 'Jenny y Bruno revisaron el one-pager para el Comité Ejecutivo del banco: resumen, roadmap, avance en cifras, logros, puntos de atención y próximos hitos. Se ajustó la redacción para distinguir prerrequisitos de apertura de requisitos funcionales de Apple.', 'La apertura de la implementación se presenta como esperada para el 15/10, no como prevista. Se retira diciembre de los próximos hitos.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and r.data='2026-10-06'::date and lower(r.titulo)=lower('Revisión interna del one-pager ejecutivo'));
