insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BancoEstado')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'semanal', '2026-10-14'::date, 'Weekly con el cliente', 'El contrato con Apple quedó firmado y cargado en el Partner Hub. CS pidió al banco confirmar que acepta avanzar sin PAN Source y dar una fecha de cumplimiento; el banco aceptó pero no dio fecha. El NDA de FIME seguía en la fiscalía del banco. La integración del SDK la hará Veritran.', 'Condición para la sesión guiada de reportería: completar antes los módulos 1, 2 y 14 de VAP.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and r.data='2026-10-14'::date and lower(r.titulo)=lower('Weekly con el cliente'));
