insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BancoEstado')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'semanal', '2026-10-21'::date, 'Weekly con el cliente', 'El Comité Ejecutivo del 15/10 se canceló y pasó al 02/11. PAN Source 06 es lo que bloquea la apertura. El banco firmó el NDA de FIME el 19/10 y abrió cerca de 55 cuestionarios en el Partner Hub. El banco dijo que no piensa pedir excepciones a Apple.', 'Weekly los miércoles a las 12:00 de Chile, 45 minutos. Tras la apertura habrá dos instancias: esta y el track técnico.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and r.data='2026-10-21'::date and lower(r.titulo)=lower('Weekly con el cliente'));
