insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BancoEstado')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'adhoc', '2026-10-28'::date, 'Alineamiento interno previo a la weekly', 'El banco respondió con mayo de 2027 como fecha de cumplimiento de PAN Source. CS no recomendaba abrir el proyecto sin los pendientes; producto propuso abrir con fecha límite en diciembre y escalar. No hay transcripción de la weekly con el cliente de ese día.', 'Llevar el tema a la weekly como riesgo en rojo y consultar a CS qué fecha exigir.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and r.data='2026-10-28'::date and lower(r.titulo)=lower('Alineamiento interno previo a la weekly'));
