insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BancoEstado')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')), 'semanal', '2026-11-11'::date, 'Weekly con el cliente (conducida por Bruno Medeiros)', 'Tras la capacitación del 05/11 hubo consenso en que el banco ya soporta PAN Source; el prerrequisito se dio por cumplido y la apertura fue solicitada, a la espera del OK formal de CS. Se esperaba el kickoff técnico la semana del 16/11. El banco pidió la matriz de riesgos actualizada.', 'Ya no se exige la fecha de diciembre. Tap to Add se trata dentro de la implementación. Tras la apertura, dos reuniones semanales.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and r.data='2026-11-11'::date and lower(r.titulo)=lower('Weekly con el cliente (conducida por Bruno Medeiros)'));
