insert into clientes (nome, pais, segmento, contatos) select 'Naranja X', 'Argentina', 'Fintech', 'Naranja X: Gabriela "Gaby" Conte (medios de pago), Ariel (interlocutor; reemplaza a Marcos Mambrín), Cristian "Cris" (decisor), Federico Cánepa (contrato). Equipo Pismo: Fede (comercial), Leonel "Leo" Cuevas (técnico). Nombres tomados de transcripciones, sin validar.' where not exists (select 1 from clientes where lower(nome)=lower('Naranja X'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'Naranja X — Migración de prepago/débito a Pismo (PMO Visa)', 'Em andamento', 'Jenny Johansen (lidera desde ~06–13/10; Lina Torres fue nombrada PM el 28–29/09) · apoyo: Bruno Medeiros', null, null::date, 'Acompañamiento Visa (PMO + capacitaciones, contrato de advisory de 6 meses) al cambio de procesador del prepago y débito Visa de Naranja X: de Global Processing a Pismo. Naranja ejecuta, Pismo habilita la plataforma y Visa coordina las tres partes. Crédito (Prisma) fuera de alcance. Kickoff con el cliente ~30/09/2026 (día no confirmado). Estrategia: primero un BIN nuevo de débito y después la migración Big Bang de los BIN actuales. Roadmap preliminar del 11/11: junio; el cliente quiere mayo (año no dicho; 2027 por deducción, a confirmar). Estado al 16/11: contrato Naranja–Pismo firmado, pero Pismo no da fecha de kickoff por falta de recursos y CS no abre el proyecto. Nota: el cliente llama al proyecto "Switch Débito" / "autoprocesamiento"; el término no está definido en las reuniones y Pismo pide no usarlo. Fuente: transcripciones automáticas no validadas.', 'rojo' from clientes c where lower(c.nome)=lower('Naranja X') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')), 'Contrato Naranja–Pismo y Solution Design', 'Pre-proyecto', 'Em curso', true, 'Fede (equipo Pismo) / Leonel Cuevas', null, 'Redactar y enviar a los abogados de Naranja la adenda sobre el archivo de clearing sin procesar; firma formal del Solution Design.', 'Contrato cerrado y firmado entre el 05 y el 11/11 (fecha exacta no dicha); fecha efectiva acordada 01/11. Queda pendiente la adenda por PCI. Solution Design en versión 4, firma formal no confirmada.', 'amarelo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Contrato Naranja–Pismo y Solution Design'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Contrato Naranja–Pismo y Solution Design')), 'Fecha efectiva acordada del contrato Naranja–Pismo', '2026-11-01'::date, true, 0 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Contrato Naranja–Pismo y Solution Design')) and lower(m.nome)=lower('Fecha efectiva acordada del contrato Naranja–Pismo'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Contrato Naranja–Pismo y Solution Design')), 'Contrato Naranja–Pismo firmado (entre 05 y 11/11, día no confirmado)', null::date, true, 1 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Contrato Naranja–Pismo y Solution Design')) and lower(m.nome)=lower('Contrato Naranja–Pismo firmado (entre 05 y 11/11, día no confirmado)'));
