insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Contrato Naranja–Pismo y Solution Design')), 'Adenda/cláusula del archivo de clearing sin procesar (responsabilidad PCI de Naranja)', 'em_andamento', 'Abogados Pismo/Visa → abogados Naranja; Fede acompaña', null::date, 'El contrato no quedó atado a esta definición (decisión del 28/10).', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Contrato Naranja–Pismo y Solution Design')) and lower(x.titulo)=lower('Adenda/cláusula del archivo de clearing sin procesar (responsabilidad PCI de Naranja)'));
