insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')), 'Apertura del proyecto Visa y kickoff', 'Apertura', 'Bloqueado', true, 'Melina Albornoz (CS Implementations)', null, 'Obtener de Pismo la fecha de kickoff y la asignación de recursos; con eso CS abre el proyecto.', 'Al 16/11 Pismo designó PM (13/11) pero no da fecha de kickoff por falta de recursos; CS no abre el proyecto sin eso. Además, el kickoff Visa solo ocurre con la integración Naranja–Pismo avanzada.', 'rojo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Apertura del proyecto Visa y kickoff'));
