insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Naranja X')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')), 'adhoc', '2026-10-06'::date, 'Contexto Pismo/Naranja X para Jenny (interna)', 'Lina sale de licencia y Jenny asume el proyecto con apoyo de Bruno. Fede define el rol del PMO: coordinar Pismo, Visa y cliente con un mensaje único, sin responder técnicamente por Pismo. Ningún plazo es firme antes del Solution Design.', 'Preguntas técnicas se derivan a Fede y Leo. Crédito fuera de alcance.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and r.data='2026-10-06'::date and lower(r.titulo)=lower('Contexto Pismo/Naranja X para Jenny (interna)'));
