insert into clientes (nome, pais, segmento, contatos) select 'Banco Provincia', 'Argentina', 'Banco', 'Banco: Damián (interlocutor principal), Fede, Sofía, Gonzalo Campana (subgerente de productos). Visa: Rafael Polo, Juan Pablo, Lucía, Moisés Salas, Laura Gómez. Cargos y apellidos a confirmar.' where not exists (select 1 from clientes where lower(nome)=lower('Banco Provincia'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'Banco Provincia — Squad de Autorizaciones y Fraude', 'Em andamento', 'Bruno Medeiros (nexo VIS); lidera frente al banco: Rafael Polo', null, null::date, 'Consultoría en formato squad (no es implementación de sistema): diagnóstico de autorizaciones y fraude, roadmap y seguimiento semanal, más lectura trimestral del informe de disputas. Contrato firmado ~jun/2026. Desde oct/2026 hay seguimiento semanal con el banco. Fuente: transcripciones automáticas de sep–nov/2026, no validadas.', null from clientes c where lower(c.nome)=lower('Banco Provincia') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')), 'Autorizaciones y Fraude', 'Consultoría de riesgo', 'Em curso', true, 'Rafael Polo', null, 'El banco cruza la base de 214.000 tarjetas con mora/bajas y con el aumento de límites de octubre, y decide si hace un aumento adicional enfocado en cross-border.', 'Diagnóstico presentado (17/09, fecha a confirmar) y seguimiento semanal activo; el 30/10 fue el tercer seguimiento. Foco inicial: rechazos por fondos insuficientes en operaciones internacionales. Otros temas abiertos: Redlink (límite de excepción), tokenización, agrupación de BINs. No hay evidencia de que el debrief y la sesión de acuerdo de roadmap se hayan realizado.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Autorizaciones y Fraude'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Autorizaciones y Fraude')), 'Cruzar la base de 214.000 tarjetas con mora/bajas y con el aumento de octubre; evaluar aumento adicional', 'em_andamento', 'Banco (Damián / inteligencia comercial)', null::date, 'Base enviada por caso en Visa Access antes del 30/10. La decisión es del banco.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Autorizaciones y Fraude')) and lower(x.titulo)=lower('Cruzar la base de 214.000 tarjetas con mora/bajas y con el aumento de octubre; evaluar aumento adicional'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Autorizaciones y Fraude')), 'Confirmar que Damián descargó el archivo del caso en Visa Access y lo envió a analizar', 'aberto', 'Fede (banco)', null::date, 'El caso está a nombre de Damián; solo él accede.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Autorizaciones y Fraude')) and lower(x.titulo)=lower('Confirmar que Damián descargó el archivo del caso en Visa Access y lo envió a analizar'));
