insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Banco Provincia')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')), 'adhoc', '2026-09-08'::date, 'Alineación interna Banco Provincia (Moisés, Rafa, Bruno)', 'Primera conversación entre Bruno y Rafael Polo. Se definieron los roles y la secuencia posterior al diagnóstico: debrief, sesión de acuerdo de roadmap y gobernanza recurrente. Rafa mostró el deck del diagnóstico, con recomendaciones priorizadas por impacto y complejidad.', 'Rafa lidera frente al banco; Bruno es el nexo con VIS en rol habilitador y cubre a Rafa en ausencias; Moisés apoya de forma periférica.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and r.data='2026-09-08'::date and lower(r.titulo)=lower('Alineación interna Banco Provincia (Moisés, Rafa, Bruno)'));
insert into reunion_tracks (reuniao_id, track_id) select (select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and r.data='2026-09-08'::date and lower(r.titulo)=lower('Alineación interna Banco Provincia (Moisés, Rafa, Bruno)')), (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Autorizaciones y Fraude')) where not exists (select 1 from reunion_tracks rt where rt.reuniao_id=(select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and r.data='2026-09-08'::date and lower(r.titulo)=lower('Alineación interna Banco Provincia (Moisés, Rafa, Bruno)')) and rt.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Autorizaciones y Fraude')));
