insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Banco Provincia')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')), 'semanal', '2026-10-27'::date, 'Weekly con el banco — rechazos por fondos insuficientes cross-border', 'Visa presentó el análisis de rechazos por fondos insuficientes en operaciones internacionales: 244.000 tarjetas con al menos un rechazo, 214.000 siguen activas. El banco informó que a inicios de octubre aumentó el límite de unas 600.000 cuentas. Temas abiertos listados: Redlink, tokenización, agrupación de BINs.', 'Proponer un aumento de línea enfocado en las 214.000 tarjetas, luego de que el banco excluya las que están en mora o dadas de baja.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and r.data='2026-10-27'::date and lower(r.titulo)=lower('Weekly con el banco — rechazos por fondos insuficientes cross-border'));
