insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Banco Provincia')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')), 'semanal', '2026-10-30'::date, 'Weekly con el banco — tercer seguimiento', 'La base de 214.000 tarjetas fue enviada por caso en Visa Access a nombre de Damián. Se entregó el gasto internacional por comercio y rubro en dólares; el banco pidió ampliarlo a pesos y a consumo local. Redlink queda en espera hasta la presentación de la nueva ejecutiva de cuentas.', 'Procedimiento para la base: excluir mora/cerradas, revisar las que ya tuvieron aumento y evaluar ajuste (decisión del banco). Redlink en standby.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and r.data='2026-10-30'::date and lower(r.titulo)=lower('Weekly con el banco — tercer seguimiento'));
