insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Banco Provincia')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')), 'adhoc', '2026-11-12'::date, 'Lectura del informe trimestral de disputas', 'Primera vez que el informe trimestral de disputas se expone al banco; período junio–agosto de 2026, con benchmark de emisores del Cono Sur. El banco presentó a Gonzalo Campana, nuevo subgerente del área de productos. La transcripción se corta a los ~10 minutos y no registra resultados.', 'Próxima lectura en diciembre de 2026.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and r.data='2026-11-12'::date and lower(r.titulo)=lower('Lectura del informe trimestral de disputas'));
insert into reunion_tracks (reuniao_id, track_id) select (select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and r.data='2026-11-12'::date and lower(r.titulo)=lower('Lectura del informe trimestral de disputas')), (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Disputas')) where not exists (select 1 from reunion_tracks rt where rt.reuniao_id=(select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and r.data='2026-11-12'::date and lower(r.titulo)=lower('Lectura del informe trimestral de disputas')) and rt.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Disputas')));
insert into clientes (nome, pais, segmento, contatos) select 'BCI', 'Chile', 'Banco', 'Sin contactos del banco confirmados. ''Tiago'' reprogramó la reunión de noviembre (empresa y cargo a confirmar).' where not exists (select 1 from clientes where lower(nome)=lower('BCI'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'BCI — Featurespace (preventa)', 'Em andamento', 'Bruno Medeiros (indicado; sin designación formal)', null, null::date, 'Preventa, no es un proyecto en ejecución: migración de la plataforma de riesgo ARIC (Featurespace) del BCI de infraestructura propia a SaaS. Assessment de Visa concluido (~ago–sep/2026); propuesta por fases armada; contrato no firmado al 16/11/2026. La identificación del BCI como cliente de esta migración está confirmada solo parcialmente. Sin Client Services.', null from clientes c where lower(c.nome)=lower('BCI') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('BCI — Featurespace (preventa)'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')), 'Preventa Featurespace', 'Riesgo', 'Pendente', false, 'Soledad Rúa y Rodri (conversación comercial)', null, 'Reunión con el banco el 18/11/2026 (lideran Rodri y Sole).', 'Propuesta de migración a SaaS por fases. Estimación de esfuerzo que circuló el 05/10: 123 días / US$ 184.000 (a validar). Licencias del banco renovadas temporalmente hasta diciembre. El equipo de analítica no tiene capacidad antes de Q2 FY27. La reunión del 11/11 fue cancelada y reprogramada.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')), 'Reunión con el banco (Rodri + Sole)', '2026-11-18'::date, false, 0 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) and lower(m.nome)=lower('Reunión con el banco (Rodri + Sole)'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')), 'Reunión con ''Tiago'' (BCI)', 'aberto', 'Rodri + Soledad Rúa', '2026-11-18'::date, 'Reprogramada tras la cancelación del 11/11. No queda claro el tema exacto.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) and lower(x.titulo)=lower('Reunión con ''Tiago'' (BCI)'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')), 'Definir la línea base de costos y enviar la propuesta', 'aberto', 'Rodri / Soledad Rúa', null::date, 'El banco pasó datos de costo distintos en dos momentos (dicho el 13/10).', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) and lower(x.titulo)=lower('Definir la línea base de costos y enviar la propuesta'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')), 'Arquitecturas as-is / to-be de la propuesta', 'em_andamento', 'Lina Torres; Bruno apoya', null::date, 'Entregable de la semana del 02/11; sin evidencia de cierre.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) and lower(x.titulo)=lower('Arquitecturas as-is / to-be de la propuesta'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')), 'Reservar recursos de analítica para la migración', 'aberto', 'Felipe', null::date, 'Realista recién en Q2 FY27; requiere reserva anticipada.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) and lower(x.titulo)=lower('Reservar recursos de analítica para la migración'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')), 'Confirmar que la ficha ''plataforma de riesgo SaaS'' corresponde al BCI', 'aberto', 'Bruno / Lina Torres', null::date, null, 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) and lower(x.titulo)=lower('Confirmar que la ficha ''plataforma de riesgo SaaS'' corresponde al BCI'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')), 'Capacidad insuficiente del equipo de analítica: ejecución recién en Q2 FY27.', 'riesgo', 'alta', 'Soledad Rúa', 'abierto', 'No prometer Q1 al cliente; reservar recursos con anticipación.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) and lower(x.descricao)=lower('Capacidad insuficiente del equipo de analítica: ejecución recién en Q2 FY27.'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')), 'Las licencias temporales del banco vencen en diciembre sin el paso a SaaS firmado.', 'riesgo', 'media', 'Rodri', 'abierto', null where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) and lower(x.descricao)=lower('Las licencias temporales del banco vencen en diciembre sin el paso a SaaS firmado.'));
insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BCI')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')), 'adhoc', '2026-10-05'::date, 'Alineación interna de oportunidades Featurespace (BCI / Banco de Chile)', 'Revisión interna de la estimación de la migración (123 días / US$ 184.000) y de la falta de recursos de analítica antes de Q2. Buena parte de la reunión trató la oportunidad de Banco de Chile, que es distinta. La grabación empieza a mitad de la conversación y no nombra al cliente de la migración.', 'No prometer Q1 al cliente; trabajar con Q2.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and r.data='2026-10-05'::date and lower(r.titulo)=lower('Alineación interna de oportunidades Featurespace (BCI / Banco de Chile)'));
insert into reunion_tracks (reuniao_id, track_id) select (select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and r.data='2026-10-05'::date and lower(r.titulo)=lower('Alineación interna de oportunidades Featurespace (BCI / Banco de Chile)')), (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) where not exists (select 1 from reunion_tracks rt where rt.reuniao_id=(select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and r.data='2026-10-05'::date and lower(r.titulo)=lower('Alineación interna de oportunidades Featurespace (BCI / Banco de Chile)')) and rt.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')));
insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BCI')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')), 'adhoc', '2026-10-09'::date, 'Demo Featurespace (plataforma ARIC) para el equipo', 'Demo inicial estándar de ARIC: dashboards, reportes, multi-tenancy, incidentes y marcado de fraude. No se llegó a la parte de analítica, que quedó para una segunda sesión. Se mencionaron abiertamente las limitaciones de reportería y la suspensión de las pruebas de concepto analíticas.', null where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and r.data='2026-10-09'::date and lower(r.titulo)=lower('Demo Featurespace (plataforma ARIC) para el equipo'));
insert into reunion_tracks (reuniao_id, track_id) select (select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and r.data='2026-10-09'::date and lower(r.titulo)=lower('Demo Featurespace (plataforma ARIC) para el equipo')), (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')) where not exists (select 1 from reunion_tracks rt where rt.reuniao_id=(select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and r.data='2026-10-09'::date and lower(r.titulo)=lower('Demo Featurespace (plataforma ARIC) para el equipo')) and rt.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace')));
insert into clientes (nome, pais, segmento, contatos) select 'BROU — Banco de la República Oriental del Uruguay', 'Uruguay', 'Banco', 'BROU: Jimena (BRM, accesos VDP, dudas Apple), Alfredo (transaccional), Luis [rol a confirmar], Luis Rocco [grafía a confirmar]. Visa: Jenny Johansen (PM), Bruno Medeiros (acompaña y cubre ausencias), Desi (pricing/renovación), Fernando (Implementation Manager, CS), Franco (CS, cubre a Fernando), Meli (líder de implementaciones CS), Vanessa (BD). Terceros: HCT (Carlos), FIME.' where not exists (select 1 from clientes where lower(nome)=lower('BROU — Banco de la República Oriental del Uruguay'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'BROU — Journey Digital', 'Em andamento', 'Jenny Johansen', 'Emiliano', '2026-04-14'::date, 'Roadmap digital del BROU: tokenización VTS COF / e-commerce, Click to Pay, Google Pay, Apple Pay, Garmin Pay y mandatos OCT-AFT y ANI. Estado al 16/11/2026 (fuente: reuniones internas Visa, transcripciones automáticas no validadas): contrato VCA renovado y firmado antes del 19/10; 5 tracks en implementing; Apple Pay en warning porque el banco perdió las fechas de laboratorio FIME y el lanzamiento del 01/12 no ocurre; Click to Pay en enrolamiento masivo; Garmin completado; OCT-AFT retirado de la pipeline (recuperable); ANI sin proyecto abierto en CS. Feature Space es un prospecto aparte, en espera. No hay transcripción de reunión con el banco posterior al 19/08.', 'amarelo' from clientes c where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('BROU — Journey Digital'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'Tokenización Tarjeta Débito', 'Tokenização TD', 'Concluído', true, 'Jenny Johansen', 'Fernando', 'Confirmar con Fernando / el banco que la configuración productiva (27/08) y el go-live formal (03/09) ocurrieron.', 'Al 19/08: certificación concluida, configuración productiva prevista para el 27/08, piloto Friends & Family de 5 días dentro de la whitelist y go-live formal (remoción de la whitelist) estimado para el 03/09; proyecto adelantado. El resultado no consta en las transcripciones; desde octubre las billeteras y Click to Pay figuran con proyecto abierto, por lo que se asume concluida [deducción, a confirmar]. Visa ya no envía reglas BRM sugeridas: valida las que propone el emisor.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Tokenización Tarjeta Débito'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Tokenización Tarjeta Débito')), 'Fin de la configuración productiva (previsto; realización no confirmada)', '2026-08-27'::date, false, 0 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Tokenización Tarjeta Débito')) and lower(m.nome)=lower('Fin de la configuración productiva (previsto; realización no confirmada)'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Tokenización Tarjeta Débito')), 'Go-live formal: remoción de la whitelist (estimado; realización no confirmada)', '2026-09-03'::date, false, 1 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Tokenización Tarjeta Débito')) and lower(m.nome)=lower('Go-live formal: remoción de la whitelist (estimado; realización no confirmada)'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Tokenización Tarjeta Débito')), 'Confirmar la realización de la configuración productiva y del go-live formal', 'aberto', 'Jenny Johansen / Fernando', null::date, 'Fechas previstas 27/08 y 03/09 (reunión del 19/08). Sin evidencia posterior en las transcripciones.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Tokenización Tarjeta Débito')) and lower(x.titulo)=lower('Confirmar la realización de la configuración productiva y del go-live formal'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'Click to Pay', 'Click to Pay', 'Em curso - atrasado', false, 'Jenny Johansen', null, 'Concluir el enrolamiento masivo (fase 1) y aclarar la situación del waiver que vencía el 30/09.', 'Proyecto abierto en CS; fase 1 configurada; en pruebas de carga masiva (02/11) y en enrolamiento masivo (16/11). Se implementa con proveedor propio, sin SDK Visa. Se marca atrasado porque el waiver vencía el 30/09 y la meta de subida masiva era el 01/10 (registro anterior); no se dijo si el waiver se prorrogó ni si hubo multa [a confirmar].', 'amarelo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Click to Pay'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Click to Pay')), 'Vence el waiver de Click to Pay (situación posterior no informada)', '2026-09-30'::date, false, 0 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Click to Pay')) and lower(m.nome)=lower('Vence el waiver de Click to Pay (situación posterior no informada)'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Click to Pay')), 'Concluir el enrolamiento masivo de credenciales (fase 1)', 'em_andamento', 'BROU + procesador/proveedor, con CS', null::date, 'En curso al 16/11. Sin fecha objetivo informada.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Click to Pay')) and lower(x.titulo)=lower('Concluir el enrolamiento masivo de credenciales (fase 1)'));
