insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'Google Pay', 'Google Pay', 'Em curso', false, 'Jenny Johansen', null, 'El banco debe subir información a Google (pendiente anotado el 02/11).', 'En curso. BIN de débito configurado el día 22 [mes no dicho; por contexto 22/10, a confirmar]. Pendiente anotado: el banco sube información a Google ''para evitar flujo verde'' [redacción del extracto; sentido a confirmar].', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Google Pay'));
