insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'Mandato ANI (Account Name Inquiry)', 'Mandato ANI', 'Pendente', false, 'Jenny Johansen', null, 'Aclarar quién abre el proyecto en CS.', 'En implementing en la pipeline VCA, sin proyecto abierto en CS. El 02/11 había duda sobre quién lo abre (citados Juan Carlos Arias / Liana Appleby [grafías a confirmar]). La extensión vencía el 31/08 (registro anterior); situación actual no informada.', 'amarelo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Mandato ANI (Account Name Inquiry)'));
