insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Apple Pay')), 'Apple Pay sin fecha de laboratorio FIME: el lanzamiento del 01/12 no ocurre y la nueva fecha puede caer en el freeze del banco (25/11 a enero, dato del registro anterior — a confirmar si sigue vigente).', 'issue', 'alta', 'BROU', 'abierto', 'Pedir nuevas fechas a FIME de inmediato y replanificar con el banco considerando el freeze.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Apple Pay')) and lower(x.descricao)=lower('Apple Pay sin fecha de laboratorio FIME: el lanzamiento del 01/12 no ocurre y la nueva fecha puede caer en el freeze del banco (25/11 a enero, dato del registro anterior — a confirmar si sigue vigente).'));
