insert into riscos (projeto_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'Mandatos sin ejecución: OCT-AFT retirado de la pipeline y ANI sin proyecto abierto en CS — exposición a penalidades (riesgo señalado en la Pipeline Review del 04/09).', 'riesgo', 'alta', 'BROU / Visa', 'abierto', 'Reunión con CSM y BD sobre mandatos, penalidades y waiver (tarea de Bruno del 04/09, sin evidencia de realización).' where not exists (select 1 from riscos x where x.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(x.descricao)=lower('Mandatos sin ejecución: OCT-AFT retirado de la pipeline y ANI sin proyecto abierto en CS — exposición a penalidades (riesgo señalado en la Pipeline Review del 04/09).'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Click to Pay')), 'Waiver de Click to Pay vencido el 30/09 con el enrolamiento masivo aún en curso al 16/11; no se sabe si hubo prórroga o multa.', 'riesgo', 'alta', 'BROU', 'abierto', 'Confirmar con el CSM la situación del waiver y documentar el avance del enrolamiento.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Click to Pay')) and lower(x.descricao)=lower('Waiver de Click to Pay vencido el 30/09 con el enrolamiento masivo aún en curso al 16/11; no se sabe si hubo prórroga o multa.'));
insert into riscos (projeto_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'Vigencia del contrato renovado frente al alcance restante (Apple Pay, Google Pay, Click to Pay, ANI): la fecha de fin no fue informada; con el contrato anterior CS dejó de abrir proyectos al quedar ~3 semanas.', 'riesgo', 'media', 'Jenny Johansen / Desi', 'abierto', 'Registrar la fecha de fin y empezar la conversación de continuidad con meses de anticipación.' where not exists (select 1 from riscos x where x.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(x.descricao)=lower('Vigencia del contrato renovado frente al alcance restante (Apple Pay, Google Pay, Click to Pay, ANI): la fecha de fin no fue informada; con el contrato anterior CS dejó de abrir proyectos al quedar ~3 semanas.'));
insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BROU — Banco de la República Oriental del Uruguay')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'semanal', '2026-08-19'::date, 'Seguimiento VTS COF + E-commerce', 'Configuración productiva en curso con fin previsto el 27/08. El banco debe tener la whitelist asociada a las reglas del BRM; Visa ya no envía reglas sugeridas y valida capturas con el equipo de BRM. Plan: configuración productiva, API Key, piloto Friends & Family de 5 días y go-live formal el 03/09. Proyecto adelantado respecto del plan.', '• Go-live formal = remoción de la whitelist por el banco
