insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BROU — Banco de la República Oriental del Uruguay')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'adhoc', '2026-11-10'::date, 'Alineamiento Jenny–Bruno (cobertura del 11/11)', 'El proyecto Apple Pay ya está abierto en CS y tiene seguimiento el 11/11 por la tarde, que cubre Bruno. Franco, que cubre a Fernando, debe confirmar el fin de la configuración, compartir las claves ''WSD'' [grafía a confirmar] y responder dudas de funcionalidades Apple enviadas por Jimena.', '• Bruno asiste, graba y anota pendientes del seguimiento del 11/11' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and r.data='2026-11-10'::date and lower(r.titulo)=lower('Alineamiento Jenny–Bruno (cobertura del 11/11)'));
