insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BROU — Banco de la República Oriental del Uruguay')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')), 'semanal', '2026-11-16'::date, 'Weekly Tech (interna)', 'Apple Pay en warning: el banco perdió las fechas de laboratorio FIME; quería lanzar el 01/12 y no ocurrirá. Click to Pay sigue en enrolamiento masivo. Lina crea el VPC del prospecto Feature Space BROU.', null where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and r.data='2026-11-16'::date and lower(r.titulo)=lower('Weekly Tech (interna)'));
