insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')), 'Etapa 2 CYBS — funcionalidades nativas de Nuek', 'Renovación / oportunidad', 'Pendente', false, 'Lina Torres', null, 'Obtener el OK formal del banco.', 'Propuesta para construir funcionalidades nativas de Nuek. Evolución de la cotización: 2 funcionalidades / USD 385K / 4 meses (02/11); tres tamaños (05/11); 10 funcionalidades / ~USD 900K / ~9 meses (16/11; se cotizaron 2, 5 y 10). Reunión de Soledad con Braulio el 10/11: ''positiva''. A la espera del OK formal.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Etapa 2 CYBS — funcionalidades nativas de Nuek'));
