insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')), 'Featurespace (prospecto)', 'Oportunidad', 'Sin iniciar', false, 'Lina Torres', null, 'Esperar el acuerdo de incentivos del banco y la confirmación de la interfaz VisaNet → Featurespace.', 'Oportunidad distinta de la migración. El banco quiere internalizar la gestión de fraude que hoy hace el procesador; Nuek no tiene integración con Featurespace. Sería la primera implementación prevista con transacciones directas de VisaNet a Featurespace. Enfoque aprobado por el cliente: primero assessment, después implementación. El banco indicó Q2 FY27 (02/11).', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Featurespace (prospecto)'));
