insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Etapa 2 CYBS — funcionalidades nativas de Nuek')), 'La etapa 2 no tiene OK formal y el contrato actual termina en diciembre: posible intervalo sin cobertura contractual.', 'riesgo', 'media', 'Soledad Rúa / Mica', 'abierto', 'Seguimiento con Braulio tras la reunión positiva del 10/11.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Etapa 2 CYBS — funcionalidades nativas de Nuek')) and lower(x.descricao)=lower('La etapa 2 no tiene OK formal y el contrato actual termina en diciembre: posible intervalo sin cobertura contractual.'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Migración Nexus → Nuek (estabilización y cierre)')), 'Los pendientes principales quedan para 2027 sin línea de tiempo ni responsable definido tras el cierre.', 'riesgo', 'media', 'Lina Torres', 'abierto', 'Priorizarlos con el banco y convertirlos en roadmap antes de diciembre.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Migración Nexus → Nuek (estabilización y cierre)')) and lower(x.descricao)=lower('Los pendientes principales quedan para 2027 sin línea de tiempo ni responsable definido tras el cierre.'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Casos con la marca Visa')), 'Casos con la marca sin responsable nombrado en Visa (cambio de responsable, vacaciones): el banco percibe falta de respuesta.', 'riesgo', 'media', 'Bruno Medeiros / Moisés', 'abierto', 'Nombrar responsable por caso y hacer traspaso formal en ausencias.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Casos con la marca Visa')) and lower(x.descricao)=lower('Casos con la marca sin responsable nombrado en Visa (cambio de responsable, vacaciones): el banco percibe falta de respuesta.'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Migración Nexus → Nuek (estabilización y cierre)')), 'Líneas de atención sin visibilidad del motivo de rechazo (SAT × Monitor × LCN): registrado el ~28/08; estado actual desconocido.', 'issue', 'media', 'Nuek', 'abierto', 'Nuek lo llevó a una mesa de ''glosas y flujo''; verificar si se cerró.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Migración Nexus → Nuek (estabilización y cierre)')) and lower(x.descricao)=lower('Líneas de atención sin visibilidad del motivo de rechazo (SAT × Monitor × LCN): registrado el ~28/08; estado actual desconocido.'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Featurespace (prospecto)')), 'Featurespace depende del nuevo acuerdo de incentivos y de una interfaz VisaNet → Featurespace cuya disponibilidad no está confirmada; la fase 1 se estima en 4 meses y Lina estima 6 o más.', 'riesgo', 'media', 'Lina Torres', 'abierto', 'Confirmar roadmap de la interfaz antes de comprometer fechas.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Featurespace (prospecto)')) and lower(x.descricao)=lower('Featurespace depende del nuevo acuerdo de incentivos y de una interfaz VisaNet → Featurespace cuya disponibilidad no está confirmada; la fase 1 se estima en 4 meses y Lina estima 6 o más.'));
insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Banco de Chile')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')), 'adhoc', '2026-08-26'::date, '1:1 de contexto con el banco y caso de bloqueo por fraude', 'El banco explica que, tras migrar a Nuek, los bloqueos por fraude o robo no se reflejan en la marca. Estado de la estabilización: 142 tickets abiertos, 34 prioritarios, 65 en Nuek sin fecha objetivo. Bruno asume la gestión interna del caso con Visa.', '• Visa participa activamente solo donde puede acelerar con la marca
