insert into clientes (nome, pais, segmento, contatos) select 'Banco de Corrientes', 'Argentina', 'Banco', 'Banco: Juan José "Juanjo" (líder técnico), Verónica Escobar (comercial/producto), Cristian (desarrollo mobile), Martín (gerente comercial). Thales: Patricia. Prisma: Iván. Visa: Edgar Javier Cadena (PM del programa), Franco Demaria (Apple Pay, CS), Facundo Castillo (configuraciones), Valentina (cuenta), Agustín Cánovas (negocios), Desiree Ovejero (Tech), Bruno Medeiros (seguimiento hasta ~05/10).' where not exists (select 1 from clientes where lower(nome)=lower('Banco de Corrientes'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'Banco de Corrientes — Wallets & Click to Pay', 'Em andamento', 'Edgar Javier Cadena (PM del programa hasta el 30/09/2026); Bruno Medeiros (seguimiento hasta ~05/10/2026)', null, null::date, 'Programa de acompañamiento VCA de Apple Pay y Click to Pay, cerrado formalmente el 30/09/2026. Click to Pay cumplió el mandato: fase 2 en producción desde el 25/09/2026 y fase 3 con evidencias registradas. Apple Pay siguió fuera del programa, en certificación con FIME y por billing de CS (Weekly Tech 05/10: "va por billing ahora"; decisión formal del banco no registrada). La información de Apple Pay llega solo hasta el 07/10/2026; no hay fuentes posteriores sobre pre-certificación, certificación oficial ni salida a producción. Corrientes salió de la cartera VCA y de Bruno en ~05/10/2026.', null from clientes c where lower(c.nome)=lower('Banco de Corrientes') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')), 'Click to Pay', 'Mandato Click to Pay (fases 2 y 3)', 'Concluído', false, 'Banco de Corrientes (Juanjo) con Thales; seguimiento Visa: Bruno Medeiros / Edgar Javier Cadena', 'Facundo Castillo (configuraciones y casos en Support Hub)', 'Operación normal. Quedan solo temas administrativos: respuesta formal de Visa al cierre del mandato cargado en Visa Access y entrega del documento de evidencias de pruebas en producción (ATP de Thales).', 'Fase 2 (enrolamiento desde la app del banco vía SDK Thales) productiva desde el 25/09/2026, cinco días antes del plazo del mandato (30/09). Fase 3 (logo en credenciales) con evidencias registradas. El banco cargó el cierre en Visa Access el 29/09. Camino: producción controlada (TestFlight y grupo de prueba de Google Play), decidida en ~04/09 porque el ambiente de prueba de Visa no tenía la configuración Thales–banco. Sin desenlace registrado para el cobro de USD 5.000 de Rules ni para el costo de USD 350 del sandbox (el 03/09 se decidió no cobrarlo esa vez).', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Click to Pay'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Click to Pay')), 'Fase 2 en producción', '2026-09-25'::date, true, 0 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Click to Pay')) and lower(m.nome)=lower('Fase 2 en producción'));
