insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Click to Pay')), 'Definir el destino del cobro de USD 5.000 (Rules)', 'aberto', 'Agustín Cánovas / Valentina con Rules', null::date, 'Rules respondió el 27/08 que no se puede reembolsar; VIS no lo cubre. Sin desenlace registrado [a confirmar].', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Click to Pay')) and lower(x.titulo)=lower('Definir el destino del cobro de USD 5.000 (Rules)'));
