insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')), 'Apple Pay', 'Wallets — Apple Pay (certificación FIME y Partner Hub)', 'Em curso', true, 'Banco de Corrientes (Juanjo); referencia Visa: Franco Demaria (CS)', 'Franco Demaria', 'Último estado conocido (07/10/2026): diagnosticar el error de push provisioning en pruebas productivas durante la pre-certificación FIME y seguir a la certificación oficial (planificada para el 25 o 26/10 [a confirmar]). Sin información posterior.', 'Estado al 07/10/2026 — sin fuentes posteriores. Configuraciones Visa/VRM concluidas (falta liberar la whitelist el día de la salida a producción); contrato validado por Apple; identificador de la app y wireframe cargados en Partner Hub; app unificada integrada en ~01/10. Pre-certificación FIME iniciada el 05/10. El 07/10, en prueba productiva de push provisioning la wallet se cierra y el pedido no aparece en VRM ni llega a Prisma; causa no identificada. Fuera del programa VCA desde el 30/09; sigue por billing de CS (USD 3.000 por mes según Weekly Tech del 29/09), sin decisión formal del banco registrada.', 'amarelo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Apple Pay'));
