insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Apple Pay')), 'Error productivo de push provisioning en plena pre-certificación FIME (07/10): la wallet se cierra y el pedido no aparece en VRM ni llega a Prisma. Puede consumir la ventana del laboratorio. Estado posterior desconocido.', 'issue', 'alta', 'Franco Demaria (Visa) / Juanjo (banco) / Iván (Prisma)', 'abierto', 'Ticket con evidencias; equipo de riesgos valida reglas de VRM; verificación del lado Visa pedida a Franco.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Apple Pay')) and lower(x.descricao)=lower('Error productivo de push provisioning en plena pre-certificación FIME (07/10): la wallet se cierra y el pedido no aparece en VRM ni llega a Prisma. Puede consumir la ventana del laboratorio. Estado posterior desconocido.'));
