insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Banco de Corrientes')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')), 'adhoc', '2026-09-02'::date, 'Escalamiento interno del costo de USD 350 del ambiente de prueba', 'Bruno escala el pedido de soporte de crear un sandbox con costo de USD 350 para analizar el error de Click to Pay. Explica que el cliente está en renovación y ya tuvo un cobro de USD 5.000. Pide evitar el cobro y no frenar Click to Pay.', 'Sin decisión registrada en la reunión; queda pendiente.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and r.data='2026-09-02'::date and lower(r.titulo)=lower('Escalamiento interno del costo de USD 350 del ambiente de prueba'));
