insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Banco de Corrientes')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')), 'steerco', '2026-09-30'::date, 'SteerCo de cierre del programa Apple Pay y Click to Pay', 'Click to Pay: fase 2 productiva desde el 25/09 y fase 3 con evidencias; mandato cumplido antes del plazo. Apple Pay sale del programa con ruta de certificación confirmada: pre-certificación FIME el 05/10 y certificación oficial el 25/10 [fecha a confirmar]. Thales pide el documento de evidencias de pruebas en producción para su handover a operaciones.', 'Se cierra el programa y su gobernanza. Apple Pay sigue en seguimiento técnico; los desvíos que afecten a FIME escalan por el canal técnico sin reabrir la gobernanza. Se elimina la sesión de los viernes de Click to Pay.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and r.data='2026-09-30'::date and lower(r.titulo)=lower('SteerCo de cierre del programa Apple Pay y Click to Pay'));
