insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Banco de Corrientes')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')), 'adhoc', '2026-10-07'::date, 'Errores en casos productivos — pre-certificación FIME', 'En prueba productiva de aprovisionamiento por push desde la app del banco, la wallet se cierra al lanzar el pedido. Prisma no encuentra pedidos en VRM para las tarjetas compartidas y el pedido tampoco llega a Prisma. El equipo de riesgos revisa si las reglas de VRM generan la fricción.', 'Juanjo carga el ticket con evidencias; Bruno deriva a Franco la verificación del lado Visa.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and r.data='2026-10-07'::date and lower(r.titulo)=lower('Errores en casos productivos — pre-certificación FIME'));
insert into reunion_tracks (reuniao_id, track_id) select (select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and r.data='2026-10-07'::date and lower(r.titulo)=lower('Errores en casos productivos — pre-certificación FIME')), (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Apple Pay')) where not exists (select 1 from reunion_tracks rt where rt.reuniao_id=(select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and r.data='2026-10-07'::date and lower(r.titulo)=lower('Errores en casos productivos — pre-certificación FIME')) and rt.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Apple Pay')));
insert into clientes (nome, pais, segmento, contatos) select 'BBVA Uruguay', 'Uruguay', 'Banco', 'BBVA: Diego (interlocutor principal del proyecto), Guille, Andrea (head de pagos, citada). Procesador nuevo (oído "Tohu", grafía a confirmar): Paco, Inés. Visa: Franco (Technical PM de CS), Dani (CSM), Vane/Vanessa (BD), Felipe Merea (contacto interno, rol a confirmar).' where not exists (select 1 from clientes where lower(nome)=lower('BBVA Uruguay'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'Switch/ITSP + Google Pay', 'Concluído', 'Lina Torres / Bruno Medeiros', 'Dani (apellido a confirmar)', null::date, 'Proyecto CERRADO para VCA y fuera de la cartera de Bruno (hasta el 05/10/2026). Google Pay en producción desde el 20/08/2026 con aprovisionamiento promedio ~93%. El 04/09 se decidió cerrar en ~10 días, sin extensión de contrato (contrato vencido); mail de cierre enviado por Franco (citado el ~28-29/09, fecha exacta no consta). La información técnica llega solo hasta el weekly del 31/08: quedaron SIN confirmación de desenlace la corrección del OTP por SMS (prevista 01/09), el aviso de incompatibilidad de Google Pay, los token ranges por BIN y los ~2.010 plásticos afectados por PAN replacement anticipado. Siguen vivas dos oportunidades comerciales a cargo de Lina y Desi: Apple Pay (el 16/11 el cliente aceptó los requisitos y rechazó el plazo de 4-6 meses; esperaba 3) y Featurespace (prospecto nuevo, Q2/Q3). Fuente: transcripciones automáticas no validadas.', null from clientes c where lower(c.nome)=lower('BBVA Uruguay') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('Switch/ITSP + Google Pay'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')), 'Google Pay', 'Google Pay', 'Concluído', false, 'BBVA Uruguay', 'Franco (CS)', 'Ninguno para VCA. Si se retoma el contacto, confirmar con Franco el desenlace de los puntos abiertos al 31/08.', 'En producción desde el jueves 20/08/2026 (whitelist abierta ~10:30). Aprovisionamiento: 78,5% el día 1, 95,2% el día 2, 93% el día 3; promedio ~93% (92,7%) al 31/08. Cerrado para VCA en septiembre. Último dato técnico: 31/08. Sin confirmación de cierre: corrección del OTP por SMS en el banco (prevista 01/09), respuesta de Google sobre el aviso genérico de incompatibilidad, falla in-app de un cliente y token ranges por BIN para promociones en comercios.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Google Pay'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Google Pay')), 'Go-live de Google Pay (apertura de whitelist)', '2026-08-20'::date, true, 0 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Google Pay')) and lower(m.nome)=lower('Go-live de Google Pay (apertura de whitelist)'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Google Pay')), 'Corrección del OTP por SMS en el banco (prevista; sin confirmación posterior)', '2026-09-01'::date, false, 1 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Google Pay')) and lower(m.nome)=lower('Corrección del OTP por SMS en el banco (prevista; sin confirmación posterior)'));
