insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Google Pay')), 'Corrección de la validación de celular (OTP por SMS) y verificación de que todos ven los dos métodos', 'aberto', 'BBVA (Diego/Guille) + Franco', '2026-09-01'::date, 'SIN CONFIRMACIÓN DE CIERRE. Último dato: weekly 31/08 (causa interna en el banco). Proyecto cerrado para VCA.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Google Pay')) and lower(x.titulo)=lower('Corrección de la validación de celular (OTP por SMS) y verificación de que todos ven los dos métodos'));
