insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')), 'Switch / ITSP', 'Switch / ITSP', 'Concluído', false, 'BBVA Uruguay', 'Franco (CS)', 'Ninguno para VCA.', 'Cambio de procesador (de HCT al nuevo, oído "Tohu" - grafía a confirmar). Las transcripciones no traen estado de la migración en sí; solo el caso TLCM: el banco envió en lote renovaciones futuras y ~2.010 plásticos vigentes quedaron rechazados en e-commerce y sin poder aprovisionarse hasta la vigencia de los plásticos nuevos (octubre). El 31/08 se cerró SIN solución: no existe rollback de PAN replacement. El banco pausó el lote. Sin confirmación de que se normalizó en octubre.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Switch / ITSP'));
