insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Switch / ITSP')), 'Llevar a producto la necesidad de revertir un PAN replacement (solución futura)', 'aberto', 'Franco', null::date, 'SIN CONFIRMACIÓN DE CIERRE. Último dato: 31/08.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Switch / ITSP')) and lower(x.titulo)=lower('Llevar a producto la necesidad de revertir un PAN replacement (solución futura)'));
