insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')), 'Apple Pay (prospecto)', 'Apple Pay', 'Pendente', false, 'Lina Torres / Desi', null, 'Negociar el plazo con el cliente: Visa propone 4-6 meses, el cliente esperaba 3.', 'Oportunidad comercial, no es de Bruno. Antecedente: Apple negó el waiver de Wallet Extensions (escalado hasta Miami); Wallet Extensions es prerrequisito. 05/10: entra como prospecting (BD Vane; contacto interno Felipe Merea). 02/11: el procesador nuevo desarrolla Wallet Extensions; BBVA no responde; escalado con BD. 16/11: reunión con el cliente - aceptó los requisitos y rechazó el plazo de 4-6 meses.', 'amarelo' where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Apple Pay (prospecto)'));
