insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BBVA Uruguay')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')), 'semanal', '2026-08-31'::date, 'BBVA Uruguay - Google Pay Weekly', 'Aprovisionamiento consistentemente sobre 90% desde el go-live, promedio ~93%. El banco encontró causa interna del OTP por SMS (dejó de validar bien el celular) y dejó la corrección para el 01/09. El aviso de incompatibilidad de Google Pay sigue escalado a Google. Surge el tema de promociones por BIN que no aplican con la billetera.', 'TLCM: rollback de PAN replacement cerrado sin solución; se lleva a producto. No sustituir físicamente los plásticos afectados. Esperar la corrección del banco antes de insistir con Google por el OTP.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and r.data='2026-08-31'::date and lower(r.titulo)=lower('BBVA Uruguay - Google Pay Weekly'));
