insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('BBVA Uruguay')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')), 'semanal', '2026-11-16'::date, 'Weekly Tech (interna)', 'Apple Pay: hubo reunión con el cliente ese día; aceptó los requisitos pero rechazó el plazo de 4-6 meses (esperaba 3). Lina recuerda que el Expedite sin costo en Google Pay crea precedente. Featurespace BBVA Uruguay aparece como prospecto nuevo (Q2/Q3).', 'Lina crea la oportunidad de Featurespace en VPC.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and r.data='2026-11-16'::date and lower(r.titulo)=lower('Weekly Tech (interna)'));
insert into reunion_tracks (reuniao_id, track_id) select (select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and r.data='2026-11-16'::date and lower(r.titulo)=lower('Weekly Tech (interna)')), (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Apple Pay (prospecto)')) where not exists (select 1 from reunion_tracks rt where rt.reuniao_id=(select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and r.data='2026-11-16'::date and lower(r.titulo)=lower('Weekly Tech (interna)')) and rt.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Apple Pay (prospecto)')));
insert into reunion_tracks (reuniao_id, track_id) select (select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and r.data='2026-11-16'::date and lower(r.titulo)=lower('Weekly Tech (interna)')), (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Featurespace (prospecto)')) where not exists (select 1 from reunion_tracks rt where rt.reuniao_id=(select r.id from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and r.data='2026-11-16'::date and lower(r.titulo)=lower('Weekly Tech (interna)')) and rt.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Featurespace (prospecto)')));
insert into clientes (nome, pais, segmento, contatos) select 'Comafi', 'Argentina', 'Banco', 'Comafi: interlocutor principal (posiblemente "Juli", a confirmar), Pablo (nuevo, asume gradualmente), Maxi (medios de pago, en salida). Visa: Laura (líder técnica en CS), "Mar"/"Marlene" (costos, grafía a confirmar), Facundo Castillo (CSM).' where not exists (select 1 from clientes where lower(nome)=lower('Comafi'));
insert into projetos (cliente_id, nome, status, gerente, csm, inicio, descricao, rag_override) select c.id, 'Comafi — Visa SDK + Apple Pay + Google Pay', 'Concluído', 'Lina Torres / Bruno Medeiros', 'Facundo Castillo', null::date, 'Proyecto CERRADO para VCA y fuera de la cartera de Bruno (hasta el 05/10/2026). Apple Pay en producción y estable (promedio 85,5% de aprovisionamiento del 20/07 al 20/08). El 04/09 se decidió no hacer adenda y cerrar formalmente: el contrato ya había sido extendido y estuvo ~3 meses en espera del cliente. La información técnica llega solo hasta el ~20/08 y el 27/08. SIN confirmación de desenlace: lanzamiento de Google Pay (implementación lista, bloqueada por una corrección de Mastercard en un SDK agnóstico sin release por bandera), error 303 de Apple Pay, rebranding de artes y envío del e-mail de cierre (asignado a Bruno el 04/09). Click to Pay no es parte del proyecto: el 02/11 se dijo que Comafi lo implementa por su cuenta con el SDK Visa. Fuente: transcripciones automáticas no validadas.', null from clientes c where lower(c.nome)=lower('Comafi') and not exists (select 1 from projetos p where p.cliente_id=c.id and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')), 'Apple Pay', 'Apple Pay', 'Concluído', false, 'Comafi', 'Laura (CS)', 'Ninguno para VCA. Punto focal tras el cierre: CSM (Facundo).', 'En producción. Primer mes de reporte (20/07-20/08): promedio 85,5%; últimos días 100%, 93%, 98%, 87%. Único problema técnico abierto al 27/08: error 303, con ticket en el equipo técnico de Visa y respuesta lenta - sin confirmación de solución. Corrección de arte vertical a horizontal hecha por Visa (~15/08, fecha deducida). "Apple Pay cerrado la semana pasada" dicho el 05/10.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')), 'Cierre del primer mes de reporte de aprovisionamiento (promedio 85,5%)', '2026-08-20'::date, true, 0 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')) and lower(m.nome)=lower('Cierre del primer mes de reporte de aprovisionamiento (promedio 85,5%)'));
insert into marcos (track_id, nome, fecha, concluido, orden) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')), 'Decisión: sin adenda, cierre formal', '2026-09-04'::date, true, 1 where not exists (select 1 from marcos m where m.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')) and lower(m.nome)=lower('Decisión: sin adenda, cierre formal'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')), 'Confirmar el envío del e-mail de cierre formal (recap, fases, CSM Facundo como punto focal, copia a CS)', 'aberto', 'Bruno Medeiros', null::date, 'Asignado el 04/09. El proyecto figura como cerrado con "mail de cierre" desde ~28/09, pero no hay evidencia de quién lo envió ni cuándo. Verificar también si el texto dijo que Google Pay estaba en producción.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')) and lower(x.titulo)=lower('Confirmar el envío del e-mail de cierre formal (recap, fases, CSM Facundo como punto focal, copia a CS)'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')), 'Error 303 de Apple Pay - ticket con el equipo técnico de Visa', 'aberto', 'Laura (Visa)', null::date, 'SIN CONFIRMACIÓN DE CIERRE. Último dato: 27/08.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')) and lower(x.titulo)=lower('Error 303 de Apple Pay - ticket con el equipo técnico de Visa'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')), 'Duda de concepto "activo" en el costo mensual (métricas de Apple vs. reporte de Visa)', 'aberto', 'Comafi / Mar (Visa)', null::date, 'SIN CONFIRMACIÓN DE CIERRE. Último dato: weekly ~20/08.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')) and lower(x.titulo)=lower('Duda de concepto "activo" en el costo mensual (métricas de Apple vs. reporte de Visa)'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')), 'Google Pay', 'Google Pay', 'Pendente', false, 'Comafi / Mastercard', 'Laura (CS)', 'Lanzamiento a cargo del cliente cuando Mastercard entregue su corrección; sin seguimiento VCA.', 'Implementación lista del lado Visa, pero NO lanzado al 04/09: el SDK es agnóstico (Visa + Mastercard), Comafi no segmenta releases por bandera y Mastercard debía una corrección desde hacía más de 3 meses (27/08). El proyecto se cerró sin esperar el lanzamiento. No hay ninguna reunión posterior que confirme si salió.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Google Pay'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Google Pay')), 'Lanzamiento de Google Pay (depende de la corrección de Mastercard)', 'aberto', 'Comafi / Mastercard', null::date, 'SIN CONFIRMACIÓN. Último dato: 04/09 (no lanzado).', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Google Pay')) and lower(x.titulo)=lower('Lanzamiento de Google Pay (depende de la corrección de Mastercard)'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Google Pay')), 'Monitoreo de Google Pay post-lanzamiento', 'aberto', 'Visa (Laura / CSM)', null::date, 'Previsto el 27/08 para después del lanzamiento. Sin confirmación.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Google Pay')) and lower(x.titulo)=lower('Monitoreo de Google Pay post-lanzamiento'));
insert into tracks (projeto_id, nome, frente, status, ruta_critica, responsavel, technical_pm, proximo_paso, resumo, rag_override) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')), 'Visa SDK', 'Visa SDK', 'Concluído', false, 'Comafi', 'Laura (CS)', 'Ninguno para VCA.', 'SDK / wallet extension entregado; el proyecto de SDK fue de Laura y ya está cerrado (05/10). Rebranding del banco anunciado el ~20/08: las artes nuevas deben reenviarse a Visa con la relación arte × BIN; Visa no actualiza la arte en tokens ya emitidos (hay que desenrolar y volver a enrolar) y cada aprobación de arte cuesta US$ 150. Sin registro de que el reenvío haya ocurrido.', null where not exists (select 1 from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Visa SDK'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Visa SDK')), 'Rebranding: enviar artes aprobadas por marca + relación arte × BIN para actualizar el wallet extension', 'aberto', 'Comafi → Laura', null::date, 'SIN CONFIRMACIÓN. Atado a la fecha del rebranding (no dicha). Último dato: ~20/08.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Visa SDK')) and lower(x.titulo)=lower('Rebranding: enviar artes aprobadas por marca + relación arte × BIN para actualizar el wallet extension'));
insert into tareas (track_id, titulo, status, responsavel, previsao_entrega, comentario, origen) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Visa SDK')), 'Confirmar si el texto de la tarjeta se actualiza solo en tokens existentes', 'aberto', 'Laura (Visa)', null::date, 'SIN CONFIRMACIÓN. Último dato: ~20/08.', 'reunion' where not exists (select 1 from tareas x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Visa SDK')) and lower(x.titulo)=lower('Confirmar si el texto de la tarjeta se actualiza solo en tokens existentes'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Google Pay')), 'Proyecto cerrado sin el lanzamiento de Google Pay: el cliente lanza (si lanza) sin acompañamiento VCA. Lanzamiento no confirmado.', 'issue', 'media', 'Comafi / Mastercard', 'abierto', 'CSM (Facundo) queda como punto focal tras el cierre. Último dato: 04/09.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Google Pay')) and lower(x.descricao)=lower('Proyecto cerrado sin el lanzamiento de Google Pay: el cliente lanza (si lanza) sin acompañamiento VCA. Lanzamiento no confirmado.'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')), 'Error 303 abierto al cierre, con respuesta lenta del equipo técnico. Desenlace no confirmado.', 'issue', 'baja', 'Laura (Visa)', 'abierto', 'Ticket abierto con el equipo técnico de Visa. Último dato: 27/08.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay')) and lower(x.descricao)=lower('Error 303 abierto al cierre, con respuesta lenta del equipo técnico. Desenlace no confirmado.'));
insert into riscos (track_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Visa SDK')), 'Rebranding: sin re-enrolamiento los clientes siguen viendo la arte antigua; forzarlo desactivando tokens puede reducir la base activa. Costo de US$ 150 por arte aprobada.', 'riesgo', 'baja', 'Comafi', 'abierto', 'Estrategia a criterio de Comafi; otros emisores comunicaron por e-mail pidiendo el re-enrolamiento. Último dato: ~20/08.' where not exists (select 1 from riscos x where x.track_id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Visa SDK')) and lower(x.descricao)=lower('Rebranding: sin re-enrolamiento los clientes siguen viendo la arte antigua; forzarlo desactivando tokens puede reducir la base activa. Costo de US$ 150 por arte aprobada.'));
insert into riscos (projeto_id, descricao, tipo, severidade, dueno, status, mitigacion) select (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')), 'El registro del cierre es inconsistente: la tarea del 04/09 habla de "Apple Pay y Google Pay en producción" cuando Google no estaba lanzado, y no hay evidencia del envío del e-mail de cierre.', 'issue', 'baja', 'Bruno Medeiros', 'abierto', 'Confirmar con Bruno qué se envió y cuándo.' where not exists (select 1 from riscos x where x.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(x.descricao)=lower('El registro del cierre es inconsistente: la tarea del 04/09 habla de "Apple Pay y Google Pay en producción" cuando Google no estaba lanzado, y no hay evidencia del envío del e-mail de cierre.'));
insert into reunioes (cliente_id, projeto_id, tipo, data, titulo, resumo_ia, decisoes) select (select id from clientes where lower(nome)=lower('Comafi')), (select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')), 'adhoc', '2026-08-27'::date, 'Comafi - Alineamiento interno (Bruno × Laura)', 'Bruno asume el seguimiento por la salida de Lina. Laura: proyecto listo para cerrar; falta que Comafi lance Google Pay, bloqueado por una corrección de Mastercard pendiente hace más de 3 meses. Apple Pay en producción con buenos porcentajes; queda el error 303 con ticket abierto.', 'Sin acción pendiente para Bruno; Laura lo convoca si hace falta.' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and r.data='2026-08-27'::date and lower(r.titulo)=lower('Comafi - Alineamiento interno (Bruno × Laura)'));
