-- Carga de noviembre — 2026-11-16
-- Origen: ~110 transcripciones de reuniones del 19/08 al 16/11/2026 (carpeta OneDrive .../VISA/Transcriçoes).
-- Qué hace: da de alta 8 clientes/proyectos (Grupo Petersen, BancoEstado, Naranja X, Banco Provincia, BCI,
--           Banco de Chile, BBVA Uruguay, Comafi), actualiza estado/próximo paso de BROU y Banco de Corrientes,
--           y carga tracks, marcos, tareas abiertas, riesgos y reuniones del período.
-- YA APLICADA el 16/11/2026 por la API REST (mismos datos, mismo criterio de idempotencia). Este archivo queda
-- como registro y para reconstruir la base. Reemplaza a 2026-08-19-carga-agosto-transcripciones.sql, que nunca se
-- corrió: NO correr aquel después de este (crearía proyectos duplicados con otros nombres).
-- Idempotente: todo va con `where not exists`. No borra nada. Los updates solo tocan estado/próximo paso/resumen.
-- Contenido de transcripción automática no validada: ver marcas [a confirmar] en los textos.

begin;

-- ===== Grupo Petersen =====
update projetos set status='Em andamento', gerente='Bruno Medeiros', csm=null, descricao='PMO de Visa para la integración bancaria del Grupo Petersen: Banco Entre Ríos (BERSA) y Banco San Juan se integran al Banco Santa Fe, que cambia de nombre e imagen; Banco Santa Cruz queda separado. No nace un banco nuevo. Todos procesan con Prisma y ninguno es principal member. Acompañamiento dicho de 9 meses, hasta julio de 2027. Desiree Ovejero es client facing. Solo VCA, sin CS. Fuente: transcripciones automáticas no validadas.', rag_override='amarelo' where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)'));
update tracks set status='Em curso', proximo_paso='Semanal con el cliente el jueves 19/11; armar el archivo único de seguimiento.', resumo='Kickoff hecho el 12/11. Semanal hoy los jueves; Desi quiere pedir cambio a miércoles. Propuesta interna de dos cadencias: banco+Visa y banco+Visa+Prisma.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Gobernanza PMO'));
update tracks set status='Em curso', proximo_paso='Reunión interna con Cindy el 18/11 y devolución al cliente el 19/11.', resumo='Sesión introductoria el 12/11. Tesorería Visa pide un relevamiento interno (numéricos de tesorería, jerarquías y cuentas de liquidación, licencias, nombres legales) antes de accionar a Prisma. Códigos pedidos por Cindy ya descargados (13/11). Cindy ausente del 18 al 27/11.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Tesorería y liquidación'));
update tracks set status='Pendente', proximo_paso='Visa envía el esquema; el cliente completa el cuadro de BINs y carteras.', resumo='Los BINs de San Juan y BERSA se ceden a Santa Fe. Falta el cuadro de qué queda, qué migra y hacia dónde.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('BINs y licencias'));
update tracks set status='Em curso', proximo_paso='Seguimiento con Google y Apple para obtener la respuesta por escrito.', resumo='Respuesta verbal de que la fusión no exige nada en los contratos; falta por escrito. Sin novedad al 16/11. También falta confirmar por escrito que el cliente final no tiene que volver a enrolar la tarjeta.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Billeteras y contratos Google/Apple'));
update tracks set status='Em curso', proximo_paso='Alexis envía el deck y el comunicado; el grupo estima el costo.', resumo='Demo del Visa Dynamic Metadata Updater el 16/11: actualiza arte y nombre del emisor en tokens ya provisionados sin desarrollo. Solo credenciales Visa y solo por account range. Auto-enrolamiento LAC y cobro desde 01/02/2027; precio unitario dicho de forma ambigua. Falta confirmar con Prisma que no hay nada que firmar por tokenización.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Tokenización y arte digital (VDMU)'));
update tracks set status='Pendente', proximo_paso='Responder si algún mandato exige waiver.', resumo='El cliente quiere saber ya si algún mandato exige waiver; sin respuesta al 16/11.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Mandatos'));
update tracks set status='Pendente', proximo_paso='Definición del nuevo nombre de Santa Fe por parte del grupo.', resumo='Nombre del nuevo Santa Fe sin definir. Impacta nombres legales y licencias en Visa y la cuenta en el Banco Central.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Denominación y marca'));
update tracks set status='Sin iniciar', proximo_paso='Agendar la sesión con Benefits.', resumo='Gaby tuvo reuniones internas; falta la sesión con el grupo.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Benefits'));
update tracks set status='Sin iniciar', proximo_paso='Tratar el tema en una sesión propia.', resumo='Frentes de la minuta del 22/10 no tratados hasta el 16/11. Quedó la duda del cliente sobre integración por API Gateway o directa.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Grupo Petersen') and lower(p.nome)=lower('Grupo Petersen — Proyecto Fusión (PMO integración bancaria)')) and lower(t.nome)=lower('Accesos y plataformas'));

-- ===== BancoEstado =====
update projetos set status='Em andamento', gerente='Jenny Johansen (lidera) / Bruno Medeiros (PM funcional de apoyo)', csm='Lorena Retamales', descricao='Consultoría Visa de acompañamiento para que BancoEstado implemente el SDK Visa Digital Enablement (Push Provisioning y Wallet Extension, modo headless, integrado por Veritran) y lance Apple Pay. Visa orienta y valida; no desarrolla, no certifica ni gestiona proveedores del banco. Contrato firmado la primera semana de septiembre (día exacto a confirmar); la fecha de inicio registrada es la del kickoff general (15/09/2026). Al 16/11/2026: 10 de 10 prerrequisitos de apertura cumplidos funcionalmente, apertura del proyecto técnico solicitada a CS y kickoff técnico el 25/11 según la Weekly Tech interna del 16/11 (en la weekly con el cliente del 11/11 se esperaba la semana del 16/11). Objetivo del banco: usuarios enrolando Apple Pay en mayo de 2027. Semáforo sugerido ámbar: apertura atrasada frente a la meta del 15/10, FIME sin contrato, Tap to Add sin desarrollar y cronograma sin holgura.', rag_override='amarelo' where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay'));
update tracks set status='Em curso - atrasado', proximo_paso='Obtener el OK formal de CS (Lorena Retamales / Melina) y realizar el kickoff técnico el 25/11.', resumo='Kickoff general el 15/09 con 7 de 10 prerrequisitos. Los tres restantes cerraron así: contrato Apple en el Partner Hub (antes del 14/10), registro de Veritran aprobado en PRM (informado el 04/11) y soporte de PAN Source 06 (capacitación del 05/11: el banco ya lo soporta). La meta de apertura era el 15/10. El 11/11 la apertura estaba solicitada y faltaba el OK escrito de CS; la Weekly Tech del 16/11 fija el kickoff técnico para el 25/11, con apertura oficial después.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Prerrequisitos y apertura del proyecto técnico'));
update tracks set status='Em curso', proximo_paso='Recibir la programación detallada de Veritran y reagendar la sesión técnica con los especialistas de SDK de Visa.', resumo='El banco integra en modo headless con Push Provisioning y Wallet Extension; versión entregada 5.9. La integración la hace Veritran y comenzó en octubre; el banco validó internamente un diagrama de solución sin revisión de Visa. Desarrollo estimado en 18 semanas, con término en febrero de 2027. Primera reunión de planificación de Veritran el 09/11 y reunión técnica el 12/11.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('SDK Visa Digital Enablement'));
update tracks set status='Em curso', proximo_paso='Fijar en el kickoff técnico el hito de Tap to Add y tratar artes de tarjeta y freeze de diciembre.', resumo='Contrato Apple firmado y cargado en el Partner Hub antes del 14/10; cerca de 55 cuestionarios abiertos para áreas internas del banco. El banco mantiene reuniones periódicas con Apple y declara que no piensa pedir excepciones. Tap to Add se flexibilizó solo para la apertura: es mandatorio de Apple y el banco no lo tenía desarrollado. Pendientes: Wallet Extension con biometría facial (tarea de Apple), artes de la Cuenta RUT, marketing, reglas de VRM y whitelist, alcance Mastercard.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Apple Pay — requisitos funcionales Apple'));
update tracks set status='Pendente', proximo_paso='Recibir la propuesta comercial de FIME, firmar el contrato y reservar el laboratorio en los primeros días de enero.', resumo='Contrato directo del banco con el laboratorio. NDA firmado por el banco el 19/10; primera reunión hecha antes del 04/11; el banco envió la información y espera la propuesta comercial. FIME recomienda solicitar el laboratorio a inicios de enero para comenzar pruebas en la segunda quincena de febrero: 25 días hábiles (5 de precertificación con los desarrollos en producción, más 10 y 10 de certificación formal).', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Certificación FIME'));
update tracks set status='Em curso', proximo_paso='Confirmar que la sesión guiada del 16/11 se realizó y qué dudas quedaron.', resumo='Visa no ofrece outsourcing de los reportes que exige Apple: el banco los genera en VAP. Módulos 1, 2 y 14 completados antes del 04/11. Sesión guiada convocada para el 16/11; la Weekly Tech de ese día registra una capacitación hecha [tema a confirmar]. Los reportes solo cubren Visa.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BancoEstado') and lower(p.nome)=lower('BancoEstado — Visa Digital Enablement SDK + Apple Pay')) and lower(t.nome)=lower('Reportería Apple (VAP)'));

-- ===== Naranja X =====
update projetos set status='Em andamento', gerente='Jenny Johansen (lidera desde ~06–13/10; Lina Torres fue nombrada PM el 28–29/09) · apoyo: Bruno Medeiros', csm=null, descricao='Acompañamiento Visa (PMO + capacitaciones, contrato de advisory de 6 meses) al cambio de procesador del prepago y débito Visa de Naranja X: de Global Processing a Pismo. Naranja ejecuta, Pismo habilita la plataforma y Visa coordina las tres partes. Crédito (Prisma) fuera de alcance. Kickoff con el cliente ~30/09/2026 (día no confirmado). Estrategia: primero un BIN nuevo de débito y después la migración Big Bang de los BIN actuales. Roadmap preliminar del 11/11: junio; el cliente quiere mayo (año no dicho; 2027 por deducción, a confirmar). Estado al 16/11: contrato Naranja–Pismo firmado, pero Pismo no da fecha de kickoff por falta de recursos y CS no abre el proyecto. Nota: el cliente llama al proyecto "Switch Débito" / "autoprocesamiento"; el término no está definido en las reuniones y Pismo pide no usarlo. Fuente: transcripciones automáticas no validadas.', rag_override='rojo' where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)'));
update tracks set status='Em curso', proximo_paso='Redactar y enviar a los abogados de Naranja la adenda sobre el archivo de clearing sin procesar; firma formal del Solution Design.', resumo='Contrato cerrado y firmado entre el 05 y el 11/11 (fecha exacta no dicha); fecha efectiva acordada 01/11. Queda pendiente la adenda por PCI. Solution Design en versión 4, firma formal no confirmada.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Contrato Naranja–Pismo y Solution Design'));
update tracks set status='Bloqueado', proximo_paso='Obtener de Pismo la fecha de kickoff y la asignación de recursos; con eso CS abre el proyecto.', resumo='Al 16/11 Pismo designó PM (13/11) pero no da fecha de kickoff por falta de recursos; CS no abre el proyecto sin eso. Además, el kickoff Visa solo ocurre con la integración Naranja–Pismo avanzada.', rag_override='rojo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Apertura del proyecto Visa y kickoff'));
update tracks set status='Pendente', proximo_paso='Recibir el sandbox de Pismo y empezar la integración de APIs; configurar el sandbox de Visa antes del freeze si el proyecto se abre a tiempo.', resumo='BIN nuevos pedidos y asignados, sin configurar (correcto: configurarlos antes los ataría al procesador anterior). Pismo no tiene débito en producción en Argentina, por lo que la certificación es completa (~90 días desde el kickoff Visa). Inicio probable de certificación en enero.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('BIN nuevo de débito'));
update tracks set status='Sin iniciar', proximo_paso='Confirmación formal del modelo Big Bang por parte de Naranja; asegurar la cesión de llaves por Global Processing.', resumo='Los dos BIN del producto actual (prepago + débito en el mismo plástico) migran juntos, después del BIN nuevo. Progresivo descartado "99,9%". Tokens y 3DS siguen con Thales en la fase 1; el histórico no migra.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Migración Big Bang de los BIN actuales'));
update tracks set status='Em curso', proximo_paso='Fijar día y hora del módulo 1 (semana del 16/11) y recibir el prework de Naranja.', resumo='4 módulos virtuales de ~1 h incluidos en el contrato: M1 Autorizaciones (semana del 16/11), M2 Conciliaciones y pagos + M3 Fraude y disputas (semana del 30/11), M4 Compliance de marcas (1ª semana de diciembre). No cubren el uso práctico de herramientas: eso es un entrenamiento pago cerca de producción.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Capacitaciones Visa'));
update tracks set status='Em curso - atrasado', proximo_paso='Enviar al cliente el roadmap consolidado Visa+Pismo y abrir la conversación de renovación del contrato de advisory.', resumo='Weekly de los jueves, sesiones técnicas de los miércoles, Excel de seguimiento y minuta semanal en uso. El plan consolidado está atrasado desde ~22/10 (los planes Visa y Pismo no coincidían el 03/11). Contrato de advisory de 6 meses frente a un plan de 9.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Naranja X') and lower(p.nome)=lower('Naranja X — Migración de prepago/débito a Pismo (PMO Visa)')) and lower(t.nome)=lower('Gobierno PMO y plan integrado'));

-- ===== Banco Provincia =====
update projetos set status='Em andamento', gerente='Bruno Medeiros (nexo VIS); lidera frente al banco: Rafael Polo', csm=null, descricao='Consultoría en formato squad (no es implementación de sistema): diagnóstico de autorizaciones y fraude, roadmap y seguimiento semanal, más lectura trimestral del informe de disputas. Contrato firmado ~jun/2026. Desde oct/2026 hay seguimiento semanal con el banco. Fuente: transcripciones automáticas de sep–nov/2026, no validadas.', rag_override=null where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude'));
update tracks set status='Em curso', proximo_paso='El banco cruza la base de 214.000 tarjetas con mora/bajas y con el aumento de límites de octubre, y decide si hace un aumento adicional enfocado en cross-border.', resumo='Diagnóstico presentado (17/09, fecha a confirmar) y seguimiento semanal activo; el 30/10 fue el tercer seguimiento. Foco inicial: rechazos por fondos insuficientes en operaciones internacionales. Otros temas abiertos: Redlink (límite de excepción), tokenización, agrupación de BINs. No hay evidencia de que el debrief y la sesión de acuerdo de roadmap se hayan realizado.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Autorizaciones y Fraude'));
update tracks set status='Em curso', proximo_paso='Próxima lectura del informe trimestral en diciembre de 2026 (período sep–nov).', resumo='Informe trimestral de disputas. Las dos primeras entregas se prepararon pero nunca se presentaron; el 12/11 se hizo la primera lectura formal (período jun–ago/2026, con benchmark de emisores del Cono Sur). La transcripción está truncada: no quedaron registrados los resultados.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco Provincia') and lower(p.nome)=lower('Banco Provincia — Squad de Autorizaciones y Fraude')) and lower(t.nome)=lower('Disputas'));

-- ===== BCI =====
update projetos set status='Em andamento', gerente='Bruno Medeiros (indicado; sin designación formal)', csm=null, descricao='Preventa, no es un proyecto en ejecución: migración de la plataforma de riesgo ARIC (Featurespace) del BCI de infraestructura propia a SaaS. Assessment de Visa concluido (~ago–sep/2026); propuesta por fases armada; contrato no firmado al 16/11/2026. La identificación del BCI como cliente de esta migración está confirmada solo parcialmente. Sin Client Services.', rag_override=null where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)'));
update tracks set status='Pendente', proximo_paso='Reunión con el banco el 18/11/2026 (lideran Rodri y Sole).', resumo='Propuesta de migración a SaaS por fases. Estimación de esfuerzo que circuló el 05/10: 123 días / US$ 184.000 (a validar). Licencias del banco renovadas temporalmente hasta diciembre. El equipo de analítica no tiene capacidad antes de Q2 FY27. La reunión del 11/11 fue cancelada y reprogramada.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BCI') and lower(p.nome)=lower('BCI — Featurespace (preventa)')) and lower(t.nome)=lower('Preventa Featurespace'));

-- ===== BROU — Banco de la República Oriental del Uruguay =====
update projetos set status='Em andamento', gerente='Jenny Johansen', csm='Emiliano', descricao='Roadmap digital del BROU: tokenización VTS COF / e-commerce, Click to Pay, Google Pay, Apple Pay, Garmin Pay y mandatos OCT-AFT y ANI. Estado al 16/11/2026 (fuente: reuniones internas Visa, transcripciones automáticas no validadas): contrato VCA renovado y firmado antes del 19/10; 5 tracks en implementing; Apple Pay en warning porque el banco perdió las fechas de laboratorio FIME y el lanzamiento del 01/12 no ocurre; Click to Pay en enrolamiento masivo; Garmin completado; OCT-AFT retirado de la pipeline (recuperable); ANI sin proyecto abierto en CS. Feature Space es un prospecto aparte, en espera. No hay transcripción de reunión con el banco posterior al 19/08.', rag_override='amarelo' where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital'));
update tracks set status='Concluído', proximo_paso='Confirmar con Fernando / el banco que la configuración productiva (27/08) y el go-live formal (03/09) ocurrieron.', resumo='Al 19/08: certificación concluida, configuración productiva prevista para el 27/08, piloto Friends & Family de 5 días dentro de la whitelist y go-live formal (remoción de la whitelist) estimado para el 03/09; proyecto adelantado. El resultado no consta en las transcripciones; desde octubre las billeteras y Click to Pay figuran con proyecto abierto, por lo que se asume concluida [deducción, a confirmar]. Visa ya no envía reglas BRM sugeridas: valida las que propone el emisor.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Tokenización Tarjeta Débito'));
update tracks set status='Em curso - atrasado', proximo_paso='Concluir el enrolamiento masivo (fase 1) y aclarar la situación del waiver que vencía el 30/09.', resumo='Proyecto abierto en CS; fase 1 configurada; en pruebas de carga masiva (02/11) y en enrolamiento masivo (16/11). Se implementa con proveedor propio, sin SDK Visa. Se marca atrasado porque el waiver vencía el 30/09 y la meta de subida masiva era el 01/10 (registro anterior); no se dijo si el waiver se prorrogó ni si hubo multa [a confirmar].', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Click to Pay'));
update tracks set status='Em curso', proximo_paso='El banco debe subir información a Google (pendiente anotado el 02/11).', resumo='En curso. BIN de débito configurado el día 22 [mes no dicho; por contexto 22/10, a confirmar]. Pendiente anotado: el banco sube información a Google ''para evitar flujo verde'' [redacción del extracto; sentido a confirmar].', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Google Pay'));
update tracks set status='Em curso - atrasado', proximo_paso='Obtener nuevas fechas de laboratorio FIME y cerrar los desarrollos pendientes para la certificación Apple.', resumo='Proyecto abierto en CS antes del 10/11 (CS había rechazado abrirlo el 05/10 por quedar ~3 semanas de contrato). Franco cubre a Fernando (vacaciones). Al 16/11 está en warning: el banco perdió las fechas de laboratorio FIME; quería lanzar el 01/12 y no ocurrirá. Nueva fecha no informada.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Apple Pay'));
update tracks set status='Concluído', proximo_paso='Sin próximos pasos informados.', resumo='Completed según Weekly Tech del 02/11. El 29/09 se describió como inclusión de BIN y salió de la vista de CS. Confirmar qué se entregó.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Garmin Pay'));
update tracks set status='Pendente', proximo_paso='Decidir si se retoma y cuándo.', resumo='Pasó a ''withdrawn'' en la pipeline VCA × CS el 19/10; recuperable (''puede volver''). A fines de septiembre casi sin avance. Riesgo de penalidades señalado el 04/09.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Mandato OCT-AFT'));
update tracks set status='Pendente', proximo_paso='Aclarar quién abre el proyecto en CS.', resumo='En implementing en la pipeline VCA, sin proyecto abierto en CS. El 02/11 había duda sobre quién lo abre (citados Juan Carlos Arias / Liana Appleby [grafías a confirmar]). La extensión vencía el 31/08 (registro anterior); situación actual no informada.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and lower(t.nome)=lower('Mandato ANI (Account Name Inquiry)'));
• Se usan los mismos certificados; HCT envía los Key ID productivos
• BROU envía captura de whitelist y reglas BRM para validación' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BROU — Banco de la República Oriental del Uruguay') and lower(p.nome)=lower('BROU — Journey Digital')) and r.data='2026-08-19'::date and lower(r.titulo)=lower('Seguimiento VTS COF + E-commerce'));

-- ===== Banco de Chile =====
update projetos set status='Em andamento', gerente='Lina Torres', csm='Lorena Retamales', descricao='Acompañamiento Visa (VCA/VIS + CYBS) a la migración de procesador de Banco de Chile de Nexus a Nuek, su estabilización y cierre. Estado al 16/11/2026 (fuente: transcripciones automáticas no validadas): 4 migraciones realizadas, todos los BINs migrados, 772 tickets cerrados (dato del 27/10); la migración ''va bien''; contrato vigente hasta diciembre de 2026; las dailies se detuvieron antes del 19/10; video de cierre listo desde el 28/10. Oportunidades siguientes: etapa 2 con CYBS para funcionalidades nativas de Nuek (10 funcionalidades, ~USD 900K, ~9 meses, a la espera del OK formal) y Featurespace (el banco indicó Q2 FY27).', rag_override=null where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador'));
update tracks set status='Em curso', proximo_paso='Priorizar con el banco los pendientes de 2027 y armar el roadmap antes de diciembre; confirmar el cierre formal del contrato actual.', resumo='4 migraciones realizadas, todos los BINs migrados, Friends & Family, capacitación y gestión del cambio finalizados; estabilización en etapa de cierre; 772 tickets cerrados (27/10). El 26/08 había 142 tickets abiertos (34 prioritarios, 65 sin fecha en Nuek); el dolor central era la falta de visibilidad de los rechazos entre SAT, Monitor y LCN. Las dailies se detuvieron antes del 19/10. El 16/11 la migración se describe como ''va bien''. Visa actúa como PMO; la integración la conduce el equipo CYBS.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Migración Nexus → Nuek (estabilización y cierre)'));
update tracks set status='Pendente', proximo_paso='Confirmar el desenlace de los dos casos (bloqueo por fraude y fallback manual).', resumo='Dos casos en los que el banco pidió apoyo activo de Visa. (1) Bloqueo por fraude/robo que no se reflejaba en la marca tras la migración: Visa respondió que no había problema de conectividad sino de contenido del mensaje; corrección de Nuek con fecha 07/09, desenlace no consta. (2) Fallback manual (04/09): el banco abrió caso en Visa y pidió una reunión; la posición de Visa en el audio es contradictoria [a confirmar].', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Casos con la marca Visa'));
update tracks set status='Concluído', proximo_paso='Sin próximos pasos.', resumo='Pedido de Soledad a Lina (26/10). Guion armado a partir del deck de cierre de CYBS (27/10), solo con indicadores comprobables. Video listo el 28/10 (~3 minutos). La aprobación del 30/10 no consta en las transcripciones [a confirmar].', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Video de cierre del proyecto'));
update tracks set status='Pendente', proximo_paso='Obtener el OK formal del banco.', resumo='Propuesta para construir funcionalidades nativas de Nuek. Evolución de la cotización: 2 funcionalidades / USD 385K / 4 meses (02/11); tres tamaños (05/11); 10 funcionalidades / ~USD 900K / ~9 meses (16/11; se cotizaron 2, 5 y 10). Reunión de Soledad con Braulio el 10/11: ''positiva''. A la espera del OK formal.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Etapa 2 CYBS — funcionalidades nativas de Nuek'));
update tracks set status='Sin iniciar', proximo_paso='Esperar el acuerdo de incentivos del banco y la confirmación de la interfaz VisaNet → Featurespace.', resumo='Oportunidad distinta de la migración. El banco quiere internalizar la gestión de fraude que hoy hace el procesador; Nuek no tiene integración con Featurespace. Sería la primera implementación prevista con transacciones directas de VisaNet a Featurespace. Enfoque aprobado por el cliente: primero assessment, después implementación. El banco indicó Q2 FY27 (02/11).', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and lower(t.nome)=lower('Featurespace (prospecto)'));
• Bruno verifica con Moisés quién retoma el caso' where not exists (select 1 from reunioes r where r.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Chile') and lower(p.nome)=lower('Banco de Chile × Nuek — Migración de procesador')) and r.data='2026-08-26'::date and lower(r.titulo)=lower('1:1 de contexto con el banco y caso de bloqueo por fraude'));

-- ===== Banco de Corrientes =====
update projetos set status='Em andamento', gerente='Edgar Javier Cadena (PM del programa hasta el 30/09/2026); Bruno Medeiros (seguimiento hasta ~05/10/2026)', csm=null, descricao='Programa de acompañamiento VCA de Apple Pay y Click to Pay, cerrado formalmente el 30/09/2026. Click to Pay cumplió el mandato: fase 2 en producción desde el 25/09/2026 y fase 3 con evidencias registradas. Apple Pay siguió fuera del programa, en certificación con FIME y por billing de CS (Weekly Tech 05/10: "va por billing ahora"; decisión formal del banco no registrada). La información de Apple Pay llega solo hasta el 07/10/2026; no hay fuentes posteriores sobre pre-certificación, certificación oficial ni salida a producción. Corrientes salió de la cartera VCA y de Bruno en ~05/10/2026.', rag_override=null where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay'));
update tracks set status='Concluído', proximo_paso='Operación normal. Quedan solo temas administrativos: respuesta formal de Visa al cierre del mandato cargado en Visa Access y entrega del documento de evidencias de pruebas en producción (ATP de Thales).', resumo='Fase 2 (enrolamiento desde la app del banco vía SDK Thales) productiva desde el 25/09/2026, cinco días antes del plazo del mandato (30/09). Fase 3 (logo en credenciales) con evidencias registradas. El banco cargó el cierre en Visa Access el 29/09. Camino: producción controlada (TestFlight y grupo de prueba de Google Play), decidida en ~04/09 porque el ambiente de prueba de Visa no tenía la configuración Thales–banco. Sin desenlace registrado para el cobro de USD 5.000 de Rules ni para el costo de USD 350 del sandbox (el 03/09 se decidió no cobrarlo esa vez).', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Click to Pay'));
update tracks set status='Em curso', proximo_paso='Último estado conocido (07/10/2026): diagnosticar el error de push provisioning en pruebas productivas durante la pre-certificación FIME y seguir a la certificación oficial (planificada para el 25 o 26/10 [a confirmar]). Sin información posterior.', resumo='Estado al 07/10/2026 — sin fuentes posteriores. Configuraciones Visa/VRM concluidas (falta liberar la whitelist el día de la salida a producción); contrato validado por Apple; identificador de la app y wireframe cargados en Partner Hub; app unificada integrada en ~01/10. Pre-certificación FIME iniciada el 05/10. El 07/10, en prueba productiva de push provisioning la wallet se cierra y el pedido no aparece en VRM ni llega a Prisma; causa no identificada. Fuera del programa VCA desde el 30/09; sigue por billing de CS (USD 3.000 por mes según Weekly Tech del 29/09), sin decisión formal del banco registrada.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Banco de Corrientes') and lower(p.nome)=lower('Banco de Corrientes — Wallets & Click to Pay')) and lower(t.nome)=lower('Apple Pay'));

-- ===== BBVA Uruguay =====
update projetos set status='Concluído', gerente='Lina Torres / Bruno Medeiros', csm='Dani (apellido a confirmar)', descricao='Proyecto CERRADO para VCA y fuera de la cartera de Bruno (hasta el 05/10/2026). Google Pay en producción desde el 20/08/2026 con aprovisionamiento promedio ~93%. El 04/09 se decidió cerrar en ~10 días, sin extensión de contrato (contrato vencido); mail de cierre enviado por Franco (citado el ~28-29/09, fecha exacta no consta). La información técnica llega solo hasta el weekly del 31/08: quedaron SIN confirmación de desenlace la corrección del OTP por SMS (prevista 01/09), el aviso de incompatibilidad de Google Pay, los token ranges por BIN y los ~2.010 plásticos afectados por PAN replacement anticipado. Siguen vivas dos oportunidades comerciales a cargo de Lina y Desi: Apple Pay (el 16/11 el cliente aceptó los requisitos y rechazó el plazo de 4-6 meses; esperaba 3) y Featurespace (prospecto nuevo, Q2/Q3). Fuente: transcripciones automáticas no validadas.', rag_override=null where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay'));
update tracks set status='Concluído', proximo_paso='Ninguno para VCA. Si se retoma el contacto, confirmar con Franco el desenlace de los puntos abiertos al 31/08.', resumo='En producción desde el jueves 20/08/2026 (whitelist abierta ~10:30). Aprovisionamiento: 78,5% el día 1, 95,2% el día 2, 93% el día 3; promedio ~93% (92,7%) al 31/08. Cerrado para VCA en septiembre. Último dato técnico: 31/08. Sin confirmación de cierre: corrección del OTP por SMS en el banco (prevista 01/09), respuesta de Google sobre el aviso genérico de incompatibilidad, falla in-app de un cliente y token ranges por BIN para promociones en comercios.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Google Pay'));
update tracks set status='Concluído', proximo_paso='Ninguno para VCA.', resumo='Cambio de procesador (de HCT al nuevo, oído "Tohu" - grafía a confirmar). Las transcripciones no traen estado de la migración en sí; solo el caso TLCM: el banco envió en lote renovaciones futuras y ~2.010 plásticos vigentes quedaron rechazados en e-commerce y sin poder aprovisionarse hasta la vigencia de los plásticos nuevos (octubre). El 31/08 se cerró SIN solución: no existe rollback de PAN replacement. El banco pausó el lote. Sin confirmación de que se normalizó en octubre.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Switch / ITSP'));
update tracks set status='Pendente', proximo_paso='Negociar el plazo con el cliente: Visa propone 4-6 meses, el cliente esperaba 3.', resumo='Oportunidad comercial, no es de Bruno. Antecedente: Apple negó el waiver de Wallet Extensions (escalado hasta Miami); Wallet Extensions es prerrequisito. 05/10: entra como prospecting (BD Vane; contacto interno Felipe Merea). 02/11: el procesador nuevo desarrolla Wallet Extensions; BBVA no responde; escalado con BD. 16/11: reunión con el cliente - aceptó los requisitos y rechazó el plazo de 4-6 meses.', rag_override='amarelo' where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Apple Pay (prospecto)'));
update tracks set status='Sin iniciar', proximo_paso='Crear la oportunidad en el sistema de oportunidades (VPC).', resumo='Prospecto nuevo citado el 16/11 (Q2/Q3). Sin alcance ni contacto registrados.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('BBVA Uruguay') and lower(p.nome)=lower('Switch/ITSP + Google Pay')) and lower(t.nome)=lower('Featurespace (prospecto)'));

-- ===== Comafi =====
update projetos set status='Concluído', gerente='Lina Torres / Bruno Medeiros', csm='Facundo Castillo', descricao='Proyecto CERRADO para VCA y fuera de la cartera de Bruno (hasta el 05/10/2026). Apple Pay en producción y estable (promedio 85,5% de aprovisionamiento del 20/07 al 20/08). El 04/09 se decidió no hacer adenda y cerrar formalmente: el contrato ya había sido extendido y estuvo ~3 meses en espera del cliente. La información técnica llega solo hasta el ~20/08 y el 27/08. SIN confirmación de desenlace: lanzamiento de Google Pay (implementación lista, bloqueada por una corrección de Mastercard en un SDK agnóstico sin release por bandera), error 303 de Apple Pay, rebranding de artes y envío del e-mail de cierre (asignado a Bruno el 04/09). Click to Pay no es parte del proyecto: el 02/11 se dijo que Comafi lo implementa por su cuenta con el SDK Visa. Fuente: transcripciones automáticas no validadas.', rag_override=null where id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay'));
update tracks set status='Concluído', proximo_paso='Ninguno para VCA. Punto focal tras el cierre: CSM (Facundo).', resumo='En producción. Primer mes de reporte (20/07-20/08): promedio 85,5%; últimos días 100%, 93%, 98%, 87%. Único problema técnico abierto al 27/08: error 303, con ticket en el equipo técnico de Visa y respuesta lenta - sin confirmación de solución. Corrección de arte vertical a horizontal hecha por Visa (~15/08, fecha deducida). "Apple Pay cerrado la semana pasada" dicho el 05/10.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Apple Pay'));
update tracks set status='Pendente', proximo_paso='Lanzamiento a cargo del cliente cuando Mastercard entregue su corrección; sin seguimiento VCA.', resumo='Implementación lista del lado Visa, pero NO lanzado al 04/09: el SDK es agnóstico (Visa + Mastercard), Comafi no segmenta releases por bandera y Mastercard debía una corrección desde hacía más de 3 meses (27/08). El proyecto se cerró sin esperar el lanzamiento. No hay ninguna reunión posterior que confirme si salió.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Google Pay'));
update tracks set status='Concluído', proximo_paso='Ninguno para VCA.', resumo='SDK / wallet extension entregado; el proyecto de SDK fue de Laura y ya está cerrado (05/10). Rebranding del banco anunciado el ~20/08: las artes nuevas deben reenviarse a Visa con la relación arte × BIN; Visa no actualiza la arte en tokens ya emitidos (hay que desenrolar y volver a enrolar) y cada aprobación de arte cuesta US$ 150. Sin registro de que el reenvío haya ocurrido.', rag_override=null where id=(select t.id from tracks t where t.projeto_id=(select p.id from projetos p join clientes c on c.id=p.cliente_id where lower(c.nome)=lower('Comafi') and lower(p.nome)=lower('Comafi — Visa SDK + Apple Pay + Google Pay')) and lower(t.nome)=lower('Visa SDK'));

commit;
